            function jcTotals(jc) {
                const actH = (jc.mechanicLines || []).filter(m => m.done).reduce((s, m) => s + (m.actualHours || 0), 0);
                const actP = (jc.mechanicLines || []).filter(m => m.done).reduce((s, m) => s + (m.partsCost || 0), 0);
                const actL = (jc.mechanicLines || []).filter(m => m.done).reduce((s, m) => s + (m.labourCost || 0), 0);
                const actC = (jc.mechanicLines || []).filter(m => m.done).reduce((s, m) => s + (m.actualCost || 0), 0);
                return { actH, actP, actL, actC };
            }
            function setJcPageTab(tab) {
                jcPageTab = tab;
                localStorage.setItem('fg3_jc_page_tab', jcPageTab);
                document.getElementById('jcTab-pipeline')?.classList.toggle('active', tab === 'pipeline');
                document.getElementById('jcTab-history')?.classList.toggle('active', tab === 'history');
                document.getElementById('jc-pipeline-panel').style.display = tab === 'pipeline' ? 'block' : 'none';
                document.getElementById('jc-history-panel').style.display = tab === 'history' ? 'block' : 'none';
                if (tab === 'pipeline') renderJcKanban();
                else renderJcHistory();
            }
            function populateJcTruckFilters() {
                const opts = trucks.map(t => `<option value="${xmlEscape(t.plate)}">${formatTruckLabel(t)}</option>`).join('');
                ['jobcardTruckFilter', 'historyTruckFilter'].forEach(id => {
                    const el = document.getElementById(id);
                    if (!el) return;
                    const cur = el.value;
                    el.innerHTML = `<option value="">All Trucks</option>${opts}`;
                    if (cur) el.value = cur;
                });
            }
            function renderJobCardsPage() {
                const role = getFgRole();
                loadJcStatusFilter(); // audit J6: status tab survives saves / remote refresh
                setFgRole(role);
                populateJcTruckFilters();
                renderJcMetrics();
                renderJcDuePanel();
                if (jcPageTab === 'history') renderJcHistory();
                else renderJcKanban();
            }
            function isDateInMetricsPeriod(dateValue, period) {
                if (!dateValue) return false;
                // Audit J1: compare on the LOCAL calendar (dates may be 'YYYY-MM-DD' or ISO timestamps).
                const date = /^\d{4}-\d{2}-\d{2}$/.test(String(dateValue)) ? parseYMD(dateValue) : new Date(dateValue);
                if (!date || Number.isNaN(date.getTime())) return false;
                const now = new Date();
                let start;
                if (period === 'today') start = startOfDay(now);
                else if (period === 'week') start = startOfWeek(now);
                else if (period === 'month') start = startOfMonth(now);
                else if (period === 'year') start = startOfYear(now);
                else return false;
                return date >= start && date <= endOfDay(now);
            }
            function getJcMetricTimestamp(jc) {
                if (jc.status === 'Released') return jc.releasedAt || jc.approvedAt || jc.date;
                return jc.date || jc.submittedAt || '';
            }
            function setJcMetricsPeriod(period) {
                jcMetricsPeriod = period || 'today';
                const sel = document.getElementById('jcMetricsPeriodFilter');
                if (sel) sel.value = jcMetricsPeriod;
                renderJcMetrics();
            }
            function renderJcMetrics() {
                const el = document.getElementById('jcMetrics');
                if (!el) return;
                const inPeriod = j => isDateInMetricsPeriod(getJcMetricTimestamp(j), jcMetricsPeriod);
                const draft = jobCards.filter(j => j.status === 'Draft' && inPeriod(j)).length;
                const prog = jobCards.filter(j => j.status === 'In-Progress' && inPeriod(j)).length;
                const pend = jobCards.filter(j => j.status === 'Pending-Approval' && inPeriod(j)).length;
                const released = jobCards.filter(j => j.status === 'Released' && inPeriod(j)).length;
                // Audit J9: trucks currently in the garage = trucks with an open (not Released) job card, regardless of period.
                const inGarage = new Set(jobCards.filter(j => j.status !== 'Released' && j.plate).map(j => String(j.plate).trim().toUpperCase())).size;
                const cost = jobCards.filter(j => j.status === 'Released' && inPeriod(j)).reduce((s, j) => s + jcTotals(j).actC, 0);
                const periodLabel = jcMetricsPeriod === 'today' ? 'Today' : jcMetricsPeriod === 'week' ? 'This Week' : jcMetricsPeriod === 'month' ? 'This Month' : 'This Year';
                el.innerHTML = `
                    <div class="metric-card c-blue"><div class="metric-label">Draft · ${periodLabel}</div><div class="metric-value">${draft}</div></div>
                    <div class="metric-card c-amber"><div class="metric-label">In Progress · ${periodLabel}</div><div class="metric-value">${prog}</div></div>
                    <div class="metric-card c-purple"><div class="metric-label">Pending Approval · ${periodLabel}</div><div class="metric-value">${pend}</div></div>
                    <div class="metric-card c-teal"><div class="metric-label">Released · ${periodLabel}</div><div class="metric-value">${released}</div></div>
                    <div class="metric-card c-red"><div class="metric-label">Trucks in Garage (now)</div><div class="metric-value">${inGarage}</div><div class="metric-sub">open job cards</div></div>
                    <div class="metric-card c-green"><div class="metric-label">Cost ${periodLabel}</div><div class="metric-value">${formatRwf(cost).replace('RWF ', '')}</div><div class="metric-sub">RWF</div></div>`;
            }
            function renderJcApprovedList(cards) {
                if (!cards.length) {
                    return `<div class="jc-status-section"><p style="padding:20px;font-size:13px;color:var(--text3);text-align:center">No supervisor-approved job cards yet.</p></div>`;
                }
                return `<div class="jc-status-section">
                    <div class="jc-approved-list">${cards.map(jc => {
                        const t = jcTotals(jc);
                        const approvedOn = jcApprovalTimestamp(jc).slice(0, 10);
                        return `<div class="jc-approved-row">
                            <div class="jc-approved-main">
                                <div><strong>${esc(jc.id)}</strong> · ${formatTruckLabelFromPlate(jc.plate || '')} · ${esc(jc.driver || '')}</div>
                                <div class="jc-approved-meta">${jc.date ? 'Job card date ' + esc(formatDisplayDate(jc.date)) + ' · ' : ''}Approved${jc.status === 'Released' ? ' · Released' : ''}</div>
                            </div>
                            <div class="jc-approved-cost">${formatRwf(t.actC)}</div>
                            <div style="display:flex;gap:6px">
                                <button class="btn btn-sm btn-ghost" onclick="App.openJobCardPreview('${escAttr(jc.id)}')">View</button>
                                <button class="btn btn-sm btn-ghost" onclick="App.generateJobCardReportById('${escAttr(jc.id)}')">Print</button>
                            </div>
                        </div>`;
                    }).join('')}</div>
                </div>`;
            }
            function jcStatusClass(st) {
                return st === 'Draft' ? 'jobcard-status-draft' : st === 'In-Progress' ? 'jobcard-status-progress'
                    : st === 'Pending-Approval' ? 'jobcard-status-pending' : st === 'Released' ? 'jobcard-status-released' : 'jobcard-status-approved';
            }
            function renderJcKanbanCard(jc) {
                const role = getFgRole();
                const id = escAttr(jc.id);
                const serviceCount = (jc.driverLines || []).length + (jc.mechanicLines || []).filter(m => m.unplanned).length;
                let actions = '';
                if (canActAsDriver(role) && jc.status === 'Draft') {
                    actions = `<button class="btn btn-sm btn-primary" onclick="event.stopPropagation();App.openEditJobCardModal('${id}')">Edit</button>
                        <button class="btn btn-sm btn-danger" onclick="event.stopPropagation();App.deleteJobCard('${id}')">Delete</button>`;
                } else if (canActAsMechanic(role) && jc.status === 'In-Progress') {
                    actions = `<button class="btn btn-sm btn-primary" onclick="event.stopPropagation();App.openJobCardModal('${id}')">Log Work</button>`;
                } else if (isSupervisorRole(role) && jc.status === 'Pending-Approval') {
                    actions = `<button class="btn btn-sm btn-primary" onclick="event.stopPropagation();App.openJobCardPreview('${id}')">Review</button>`;
                } else if (jc.status === 'Released') {
                    actions = `<button class="btn btn-sm btn-ghost" onclick="event.stopPropagation();App.generateJobCardReportById('${id}')">Print</button>`;
                }
                const extraLines = (jc.mechanicLines || []).filter(m => m.unplanned && m.name);
                const serviceList = [
                    ...(jc.driverLines || []).slice(0, 3).map(l => `<div class="jobcard-service-item">• ${esc(l.name)}</div>`),
                    ...extraLines.slice(0, 2).map(m => `<div class="jobcard-service-item" style="color:var(--teal)">+ ${esc(m.name)}</div>`)
                ].join('');
                const pri = jc.priority ? `<span class="badge" style="font-size:10px;${jc.priority === 'High' ? 'color:var(--red)' : jc.priority === 'Medium' ? 'color:var(--amber)' : 'color:var(--text3)'}">${esc(jc.priority)}</span>` : '';
                return `<div class="jobcard-card" onclick="App.openJobCardModal('${id}')">
                    <div class="jobcard-header">
                        <div class="jobcard-id">${esc(jc.id)} ${pri}</div>
                        <span class="jobcard-status-badge ${jcStatusClass(jc.status)}">${esc(jc.status)}</span>
                    </div>
                    <div class="jobcard-info">
                        <div>🚛 <strong>${formatTruckLabelFromPlate(jc.plate || '')}</strong></div>
                        <div>👤 ${esc(jc.driver || '')}</div>
                        <div>📅 ${esc(jc.date || '')}${jc.odometer ? ' · ⏱ ' + esc(formatOdometer(jc.odometer)) : ''} · ${serviceCount} service${serviceCount !== 1 ? 's' : ''}</div>
                    </div>
                    <div class="jobcard-services">${serviceList || '<div class="jobcard-service-item" style="color:var(--text3)">No services listed</div>'}</div>
                    <div class="jobcard-actions">${actions}</div>
                    ${canActAsMechanic(role) && !canActAsDriver(role) && jc.status === 'In-Progress' ? `<button type="button" class="jc-bin-btn" onclick="event.stopPropagation();App.deleteJobCard('${id}')" title="Move ${escAttr(jc.id)} to the Recycling Bin" aria-label="Move ${escAttr(jc.id)} to the Recycling Bin"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6M14 11v6"/></svg></button>` : ''}
                </div>`;
            }
            function renderJcCarouselBlock(cards, sectionId) {
                if (!cards.length) {
                    return `<div class="jc-status-section"><p style="padding:20px;font-size:13px;color:var(--text3);text-align:center">No job cards in this category</p></div>`;
                }
                return `<div class="jc-status-section" data-section="${sectionId}">
                    <div class="jc-carousel-wrap">
                        <button type="button" class="jc-carousel-btn jc-carousel-prev" data-section="${sectionId}" onclick="App.scrollJcCarousel('${sectionId}', -1)" disabled aria-label="Scroll left">‹</button>
                        <div class="jc-carousel-track" id="jc-track-${sectionId}" data-section="${sectionId}">${cards.map(renderJcKanbanCard).join('')}</div>
                        <button type="button" class="jc-carousel-btn jc-carousel-next" data-section="${sectionId}" onclick="App.scrollJcCarousel('${sectionId}', 1)" aria-label="Scroll right">›</button>
                    </div>
                    <div class="jc-carousel-meta" id="jc-meta-${sectionId}">
                        <span class="jc-meta-range">Showing 1–${Math.min(cards.length, 1)} of ${cards.length}</span>
                        <span class="jc-meta-remaining">${cards.length > 1 ? `<strong>${cards.length - 1}</strong> more →` : ''}</span>
                    </div>
                </div>`;
            }
            function updateJcCarouselMeta(sectionKey) {
                const track = document.getElementById('jc-track-' + sectionKey);
                const meta = document.getElementById('jc-meta-' + sectionKey);
                const prev = document.querySelector(`.jc-carousel-prev[data-section="${sectionKey}"]`);
                const next = document.querySelector(`.jc-carousel-next[data-section="${sectionKey}"]`);
                if (!track || !meta) return;
                const cards = track.querySelectorAll('.jobcard-card');
                const total = cards.length;
                const rangeEl = meta.querySelector('.jc-meta-range');
                const remEl = meta.querySelector('.jc-meta-remaining');
                if (!total) {
                    if (rangeEl) rangeEl.textContent = 'No cards';
                    if (remEl) remEl.innerHTML = '';
                    if (prev) prev.disabled = true;
                    if (next) next.disabled = true;
                    return;
                }
                const gap = 14;
                const cardW = (cards[0]?.offsetWidth || track.clientWidth) + gap;
                const scrollLeft = track.scrollLeft;
                const viewW = track.clientWidth;
                const firstIdx = Math.max(0, Math.floor((scrollLeft + gap * 0.5) / cardW));
                const visibleCount = Math.max(1, Math.ceil((viewW + gap) / cardW));
                const lastIdx = Math.min(total - 1, firstIdx + visibleCount - 1);
                const remainingRight = Math.max(0, total - 1 - lastIdx);
                const remainingLeft = firstIdx;
                if (rangeEl) rangeEl.textContent = `Showing ${firstIdx + 1}–${lastIdx + 1} of ${total}`;
                if (remEl) {
                    if (remainingRight > 0) remEl.innerHTML = `<strong>${remainingRight}</strong> more →`;
                    else if (remainingLeft > 0) remEl.innerHTML = `← <strong>${remainingLeft}</strong> earlier`;
                    else remEl.innerHTML = '<span style="color:var(--green)">All visible</span>';
                }
                if (prev) prev.disabled = scrollLeft <= 2;
                if (next) next.disabled = scrollLeft + viewW >= track.scrollWidth - 2;
            }
            function bindJcCarousels() {
                document.querySelectorAll('.jc-carousel-track').forEach(track => {
                    const key = track.dataset.section;
                    if (track._jcScrollBound) return;
                    track._jcScrollBound = true;
                    track.addEventListener('scroll', () => updateJcCarouselMeta(key), { passive: true });
                    track.addEventListener('wheel', e => {
                        if (Math.abs(e.deltaY) > Math.abs(e.deltaX)) {
                            e.preventDefault();
                            track.scrollBy({ left: e.deltaY, behavior: 'smooth' });
                        }
                    }, { passive: false });
                    requestAnimationFrame(() => updateJcCarouselMeta(key));
                });
                // Audit J11: one window listener for all carousels, registered once.
                if (!_jcResizeBound) {
                    _jcResizeBound = true;
                    window.addEventListener('resize', () => {
                        document.querySelectorAll('.jc-carousel-track').forEach(t => updateJcCarouselMeta(t.dataset.section));
                    });
                }
            }
            let _jcResizeBound = false;
            function scrollJcCarousel(sectionKey, direction) {
                const track = document.getElementById('jc-track-' + sectionKey);
                if (!track) return;
                const card = track.querySelector('.jobcard-card');
                const step = card ? card.offsetWidth + 14 : 320;
                track.scrollBy({ left: direction * step, behavior: 'smooth' });
                requestAnimationFrame(() => updateJcCarouselMeta(sectionKey));
                setTimeout(() => updateJcCarouselMeta(sectionKey), 260);
            }
            function renderJcKanban() {
                const role = getFgRole();
                if (!canActAsDriver(role) && jcStatusFilter === 'Draft') jcStatusFilter = 'In-Progress';
                updateJcStatCounts();
                const cards = getFilteredPipelineCards();
                const statusLabels = {
                    Draft: 'Draft job cards',
                    'In-Progress': 'In progress',
                    'Pending-Approval': 'Pending approval',
                    Approved: 'Supervisor approved'
                };
                const labelEl = document.getElementById('jcPipelineLabel');
                if (labelEl) {
                    labelEl.innerHTML = `${statusLabels[jcStatusFilter] || jcStatusFilter} <span>· ${cards.length} card${cards.length !== 1 ? 's' : ''}</span>`;
                }
                const board = document.getElementById('jcKanban');
                if (!board) return;
                if (jcStatusFilter === 'Approved') {
                    board.innerHTML = renderJcApprovedList(cards);
                } else {
                    const sectionId = jcStatusFilter.replace(/[^a-zA-Z0-9]/g, '_');
                    board.innerHTML = renderJcCarouselBlock(cards, sectionId);
                    bindJcCarousels();
                }
                renderJcMetrics();
                updateSidebarBadges();
            }
            function startJobCardForTruck(plate) {
                if (getActiveJobCardForTruck(plate)) {
                    showToast('This truck already has an open job card');
                    showPage('jobcards');
                    const active = getActiveJobCardForTruck(plate);
                    if (active) openJobCardModal(active.id);
                    return;
                }
                showPage('jobcards');
                setTimeout(() => openCreateJobCardModal(plate), 80);
            }
            // ── Odometer on a job card ──
            // Trucks keep no odometer of their own, so a truck's "last reading" is the highest one written
            // on its earlier job cards. It is offered as a hint, never typed into the box: an old reading
            // saved unchanged would claim the truck had not moved since.
            function odometerNumber(v) {
                const n = parseFloat(String(v == null ? '' : v).replace(/[^0-9.]/g, ''));
                return Number.isFinite(n) ? n : null;
            }
            // "145200", "145,200" and "145,200 km" all read as "145,200 km" — the old code added a second
            // "km" to a reading that already had one.
            function formatOdometer(v) {
                const n = odometerNumber(v);
                if (n === null) return String(v || '');
                return n.toLocaleString('en-US', { maximumFractionDigits: 1 }) + ' km';
            }
            function lastOdometerForPlate(plate, exceptId) {
                const p = String(plate || '').trim().toUpperCase();
                if (!p) return null;
                let best = null;
                jobCards.forEach(j => {
                    if (j.id === exceptId || String(j.plate || '').trim().toUpperCase() !== p) return;
                    const n = odometerNumber(j.odometer);
                    if (n !== null && (!best || n > best.km)) best = { km: n, date: j.date || String(j.createdAt || '').slice(0, 10), id: j.id };
                });
                return best;
            }
            function paintOdometerHint(plate) {
                const hint = document.getElementById('jcOdometerHint');
                const input = document.getElementById('jcOdometer');
                if (!hint) return;
                const editingId = input ? input.dataset.jc || '' : '';
                const last = lastOdometerForPlate(plate, editingId);
                const typed = input ? odometerNumber(input.value) : null;
                if (last && typed !== null && typed < last.km) {
                    hint.innerHTML = `<span style="color:var(--amber)">⚠ Lower than the last reading — ${esc(formatOdometer(last.km))} on ${esc(last.date || '?')} (${esc(last.id)})</span>`;
                } else if (last) {
                    hint.textContent = `Last reading: ${formatOdometer(last.km)} on ${last.date || '?'} (${last.id})`;
                } else {
                    hint.textContent = 'Vehicle mileage at service date';
                }
            }
            // Picking a plate fills in the truck's driver. A name the person typed is never overwritten —
            // only the default (the signed-in user) or a name this function filled in earlier is replaced,
            // so changing the plate again follows the new truck.
            // A job card shows people's NAMES, never an account e-mail (Oct 2026): older cards saved the
            // signed-in e-mail as the mechanic / approver, so any value containing "@" reads as no name.
            function jcPersonName(v) {
                const s = String(v == null ? '' : v).trim();
                return s && !s.includes('@') ? s : '';
            }
            function onJcTruckPlateChange(input) {
                const p = (input.value || '').trim().toUpperCase();
                const t = trucks.find(x => String(x.plate || '').trim().toUpperCase() === p);
                const drvInput = document.getElementById('jcDriver');
                if (t && drvInput) {
                    const d = drivers.find(x => String(x.license_plate || '').trim().toUpperCase() === p);
                    const current = drvInput.value.trim();
                    const replaceable = !current || current === drvInput.dataset.auto || current === getCurrentUserLabel();
                    if (d && d.name && replaceable) {
                        drvInput.value = d.name;
                        drvInput.dataset.auto = d.name;
                        drvInput.classList.add('jc-autofilled');
                        setTimeout(() => drvInput.classList.remove('jc-autofilled'), 1200);
                    }
                }
                paintOdometerHint(t ? t.plate : p);
            }
            function onDraftProofSelected(input) {
                const file = input && input.files && input.files[0];
                const label = document.getElementById('jcDraftProofLabel');
                if (file && label) {
                    label.innerHTML = `✅ Selected: <strong>${esc(file.name)}</strong> (${fmtBytes(file.size)})`;
                }
            }
            async function removeDraftProof(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc || !jc.handwrittenProof) return;
                const name = jc.handwrittenProof.name || 'the handwritten card';
                if (!await confirmDialog(`Remove "${name}" from ${jc.id}? The file itself stays in Google Drive.`, { danger: true, okLabel: 'Remove' })) return;
                delete jc.handwrittenProof;
                addAuditLog(jc, getFgRole(), 'removed handwritten proof', name);
                logAudit('jobcard.proof', 'jobCard', jc.id, 'removed ' + name);
                saveAll(['jobCards', 'auditTrail']);
                const box = document.querySelector('#modalBox .jc-proof-uploaded');
                const holder = box ? box.parentElement : null;
                if (holder) {
                    box.remove();
                    holder.insertAdjacentHTML('beforeend', draftProofBlockHtml(jc));
                } else {
                    openEditJobCardModal(jobCardId);
                }
                showToast('Handwritten card removed');
            }
            // The draft form's "Handwritten Job Card" block: the attached file, or the place to attach one.
            function draftProofBlockHtml(jc) {
                const proof = jc ? jc.handwrittenProof : null;
                const jcId = jc ? escAttr(jc.id) : '';
                if (proof) {
                    return `
                        <div class="jc-proof-uploaded" style="margin-top:10px">
                            <span class="proof-icon">${proofIsPdf(proof) ? '📄' : '🖼️'}</span>
                            <div class="proof-info">
                                <div class="proof-name">✅ ${esc(proof.name)}</div>
                                <div class="proof-meta">${fmtBytes(proof.size || 0)}</div>
                            </div>
                            <div class="proof-actions">
                                <button type="button" class="btn btn-ghost btn-xs" onclick="App.viewHandwrittenProof('${jcId}')">👁 View</button>
                                <button type="button" class="btn btn-ghost btn-xs" style="color:var(--amber)" onclick="App.replaceHandwrittenProof('${jcId}')">↺ Replace</button>
                                <button type="button" class="btn btn-danger btn-xs" onclick="App.removeDraftProof('${jcId}')">✕ Remove</button>
                            </div>
                        </div>`;
                } else {
                    return `
                        <div style="margin-top:10px">
                            <input type="file" id="jcDraftProofFile" accept=".pdf,.png,.jpg,.jpeg" style="display:none" onchange="App.onDraftProofSelected(this)">
                            <div class="jc-proof-upload-zone" id="jcDraftProofZone" style="padding:14px;border:1px dashed var(--border);border-radius:var(--radius);text-align:center;cursor:pointer;background:var(--bg3)" onclick="document.getElementById('jcDraftProofFile').click()">
                                <span class="upload-icon">📋</span>
                                <div class="upload-label" id="jcDraftProofLabel" style="font-size:12px;font-weight:600">Attach Handwritten Job Card (Optional)</div>
                                <div class="upload-hint" style="font-size:11px;color:var(--text3)">Optional — digital card can be submitted directly. Handwritten proof can also be attached later at garage, supervisor, or after approval.</div>
                            </div>
                        </div>`;
                }
            }
            function jcFormShellHtml(jc, prefillPlate) {
                const plateList = trucks.map(t => `<option value="${esc(t.plate)}">${formatTruckLabel(t)}</option>`).join('');
                const driverList = drivers.map(d => `<option value="${esc(d.name)}">${esc(d.name)} · ${formatDriverVehicleLabel(d)}</option>`).join('');
                const plateVal = jc ? (jc.plate || '') : (prefillPlate || '');
                // Driver name defaults to the assigned driver of the truck, else the logged-in user (audit J12).
                const assigned = plateVal ? drivers.find(d => String(d.license_plate || '').trim().toUpperCase() === String(plateVal).trim().toUpperCase()) : null;
                const driverVal = jc ? (jc.driver || '') : (assigned ? assigned.name : '');
                const pri = jc ? (jc.priority || 'Medium') : 'Low';
                const dateVal = jc ? (jc.date || (jc.createdAt ? String(jc.createdAt).slice(0, 10) : todayYMD())) : todayYMD();
                const trkMatch = plateVal ? trucks.find(t => String(t.plate || '').trim().toUpperCase() === String(plateVal).trim().toUpperCase()) : null;
                // Trucks keep no odometer, so a new card starts empty; the last reading is shown as a hint below.
                const odoVal = jc ? (jc.odometer || '') : '';
                const lastOdo = lastOdometerForPlate(trkMatch ? trkMatch.plate : plateVal, jc ? jc.id : '');
                const proof = jc ? jc.handwrittenProof : null;
                const jcId = jc ? escAttr(jc.id) : '';

                const draftProofHtml = draftProofBlockHtml(jc);

                return `
                        <div class="section">
                            <div class="info-grid">
                                <div class="info-cell">
                                    <div class="il">Date created / Job card date</div>
                                    <input type="date" id="jcDate" value="${esc(dateVal)}" max="${todayYMD()}"
                                        style="width:100%;padding:8px;background:var(--bg3);border:1px solid var(--border);border-radius:var(--radius);color:var(--text)">
                                    <div class="jc-combo-hint">Today or an earlier day — not a future one</div>
                                </div>
                                <div class="info-cell">
                                    <div class="il">Odometer reading (km)</div>
                                    <input type="text" id="jcOdometer" data-jc="${jcId}" value="${esc(odoVal)}" placeholder="e.g. 145,200" inputmode="numeric" autocomplete="off" oninput="App.paintOdometerHint(document.getElementById('jcTruckPlate')?.value)"
                                        style="width:100%;padding:8px;background:var(--bg3);border:1px solid var(--border);border-radius:var(--radius);color:var(--text)">
                                    <div class="jc-combo-hint" id="jcOdometerHint">${lastOdo ? esc(`Last reading: ${formatOdometer(lastOdo.km)} on ${lastOdo.date || '?'} (${lastOdo.id})`) : 'Vehicle mileage at service date'}</div>
                                </div>
                                <div class="info-cell">
                                    <div class="il">Truck / trailer</div>
                                    <input type="text" id="jcTruckPlate" list="jcTruckPlateList" value="${esc(plateVal)}" oninput="App.onJcTruckPlateChange(this)" onchange="App.onJcTruckPlateChange(this)" placeholder="Type or select plate number" autocomplete="off"
                                        style="width:100%;padding:8px;background:var(--bg3);border:1px solid var(--border);border-radius:var(--radius);color:var(--text)">
                                    <datalist id="jcTruckPlateList">${plateList}</datalist>
                                    <div class="jc-combo-hint">Shows truck plate with assigned trailer from fleet</div>
                                </div>
                                <div class="info-cell">
                                    <div class="il">Driver name</div>
                                    <input type="text" id="jcDriver" list="jcDriverList" value="${esc(driverVal)}" placeholder="Type or select driver name" autocomplete="off"
                                        style="width:100%;padding:8px;background:var(--bg3);border:1px solid var(--border);border-radius:var(--radius);color:var(--text)">
                                    <datalist id="jcDriverList">${driverList}</datalist>
                                    <div class="jc-combo-hint">Pick from roster or type any driver name</div>
                                </div>
                            </div>
                            <div style="margin-top:12px"><div class="il">Priority</div>
                                <div style="display:flex;gap:12px;margin-top:8px;font-size:13px">
                                    <label><input type="radio" name="jcPriority" value="Low" ${pri === 'Low' ? 'checked' : ''}> Low</label>
                                    <label><input type="radio" name="jcPriority" value="Medium" ${pri === 'Medium' ? 'checked' : ''}> Medium</label>
                                    <label><input type="radio" name="jcPriority" value="High" ${pri === 'High' ? 'checked' : ''}> High</label>
                                </div>
                            </div>
                        </div>
                        <div class="section">
                            <div class="section-title">Handwritten Job Card <span style="font-size:11px;font-weight:400;color:var(--text3)">(Optional)</span></div>
                            ${draftProofHtml}
                        </div>
                        <div class="section">
                            <div class="section-title">Services required</div>
                            <div id="jcServicesContainer"></div>
                            <button class="btn btn-ghost btn-sm" onclick="App.addJobCardLineRow()" style="margin-top:8px">+ Add line</button>
                        </div>`;
            }
            // prefillServices: optional array of service names (from the "Due soon" scheduler, audit J-S4).
            function openCreateJobCardModal(prefillPlate, prefillServices) {
                if (!canActAsDriver()) {
                    showToast('Only drivers (or an administrator) can create a job card');
                    return;
                }
                if (prefillPlate && getActiveJobCardForTruck(prefillPlate)) {
                    showToast('Truck already has an open job card');
                    openJobCardModal(getActiveJobCardForTruck(prefillPlate).id);
                    return;
                }
                openModal(`
                    <div class="modal-header">
                        <div><div class="modal-name">📋 Create Job Card</div><div class="modal-sub">Driver — request maintenance for garage</div></div>
                        <div class="modal-close" onclick="App.closeModal()">✕</div>
                    </div>
                    <div class="modal-body">${jcFormShellHtml(null, prefillPlate)}</div>
                    <div class="modal-actions">
                        <button class="btn btn-ghost" onclick="App.closeModal()">Cancel</button>
                        <button class="btn btn-ghost" onclick="App.saveJobCard(false)">Save draft</button>
                        <button class="btn btn-primary" onclick="App.saveJobCard(true)">Save &amp; Submit to garage</button>
                    </div>`);
                const pre = Array.isArray(prefillServices) ? prefillServices.filter(Boolean) : [];
                if (pre.length) pre.forEach(name => addJobCardLineRow(null, name));
                else addJobCardLineRow();
            }
            function openEditJobCardModal(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc || jc.status !== 'Draft') return;
                if (!canActAsDriver()) {
                    showToast('Only drivers (or an administrator) can edit drafts');
                    return;
                }
                migrateJobCard(jc);
                const id = escAttr(jc.id);
                openModal(`
                    <div class="modal-header">
                        <div><div class="modal-name">✎ Edit ${esc(jc.id)}</div><div class="modal-sub">Update draft before submitting to garage</div></div>
                        <div class="modal-close" onclick="App.closeModal()">✕</div>
                    </div>
                    <div class="modal-body">
                        ${jcFormShellHtml(jc)}
                    </div>
                    <div class="modal-actions">
                        <button class="btn btn-ghost" onclick="App.closeModal()">Cancel</button>
                        <button class="btn btn-primary" onclick="App.updateJobCard('${id}')">Save changes</button>
                        <button class="btn btn-primary" onclick="App.updateJobCardAndSubmit('${id}')">Save &amp; submit</button>
                    </div>`);
                (jc.driverLines || []).forEach(dl => addJobCardLineRow(null, dl.name));
                if (!(jc.driverLines || []).length) addJobCardLineRow();
            }
            async function updateJobCard(jobCardId, andSubmit) {
                if (_jcSaving) return false;
                _jcSaving = true;
                try { return await updateJobCardNow(jobCardId, andSubmit); } finally { _jcSaving = false; }
            }
            async function updateJobCardNow(jobCardId, andSubmit) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc || jc.status !== 'Draft') return false;
                const plate = (document.getElementById('jcTruckPlate')?.value || '').trim().toUpperCase();
                const driver = (document.getElementById('jcDriver')?.value || '').trim();
                const priority = document.querySelector('input[name="jcPriority"]:checked')?.value || 'Medium';
                const date = (document.getElementById('jcDate')?.value || '').trim() || jc.date || todayYMD();
                const odometer = (document.getElementById('jcOdometer')?.value || '').trim();
                const driverLines = collectDriverLinesFromForm();
                if (!plate || !driver || !driverLines.length) {
                    showToast('Fill truck plate, driver name, and at least one service');
                    return false;
                }
                if (jcDateProblem(date)) { showToast(jcDateProblem(date)); return false; }
                const other = getActiveJobCardForTruck(plate);
                if (other && other.id !== jc.id) {
                    showToast('Another open job card exists for this plate');
                    return false;
                }
                jc.plate = plate;
                jc.driver = driver;
                jc.priority = priority;
                jc.date = date;
                jc.odometer = odometer;
                jc.driverLines = driverLines;
                jc.mechanicLines = driverLines.map(dl => ({
                    driverLineId: dl.lineId,
                    done: false,
                    actualHours: 0,
                    partsCost: 0,
                    labourCost: 0,
                    actualCost: 0,
                    mechanic: '',
                    completedAt: null,
                    notDoneReason: '',
                    unplanned: false
                }));
                const draftFileInput = document.getElementById('jcDraftProofFile');
                if (draftFileInput && draftFileInput.files && draftFileInput.files[0]) {
                    showToast('Processing handwritten proof…');
                    const proofObj = await validateAndReadProof(draftFileInput.files[0], jc.id + '-handwritten');
                    if (proofObj) {
                        jc.handwrittenProof = await storeProofFile(jc, proofObj);
                    }
                }
                addAuditLog(jc, getFgRole(), 'updated draft', driverLines.map(l => l.name).join(', ') + ` · Date: ${date}${odometer ? ' · Odo: ' + odometer : ''}`);
                logAudit('jobcard.update', 'jobCard', jc.id, 'draft updated');
                saveAll(['jobCards', 'auditTrail']);
                if (andSubmit) {
                    submitJobCardToMechanic(jobCardId);
                    return true;
                }
                closeModal();
                renderJobCardsPage();
                showToast(`${jc.id} updated`);
                return true;
            }
            function updateJobCardAndSubmit(jobCardId) {
                updateJobCard(jobCardId, true);
            }
            // Adds one service row; `preselectName` selects a catalogue service or fills the custom field.
            function addJobCardLineRow(_unused, preselectName) {
                const container = document.getElementById('jcServicesContainer');
                if (!container) return;
                const idx = container.children.length;
                const catalog = getServiceCatalog();
                const inCatalog = preselectName && catalog.some(s => s.name === preselectName);
                const opts = serviceOptionsHtml(inCatalog ? preselectName : '');
                container.insertAdjacentHTML('beforeend', `
                    <div class="jc-line-row" data-idx="${idx}">
                        <select class="jc-line-service" onchange="App.onJcLineServiceChange(this)" style="width:100%;padding:8px;margin-bottom:8px;background:var(--bg3);border:1px solid var(--border);border-radius:var(--radius);color:var(--text)">
                            <option value="">— Custom / pick service —</option>${opts}
                            <option value="__custom__" ${preselectName && !inCatalog ? 'selected' : ''}>Custom service…</option>
                        </select>
                        <div class="jc-line-custom-wrap" style="display:${preselectName && !inCatalog ? 'block' : 'none'}">
                            <textarea class="jc-line-custom jc-multiline" rows="3" placeholder="One service per line — press Enter for the next one, e.g.&#10;1. Brake pad diff&#10;2. Gasket cover Room 1,2,3,4,5,6" oninput="App.onJcMultilineInput(this)">${preselectName && !inCatalog ? esc(preselectName) : ''}</textarea>
                            <div class="jc-multiline-preview">${preselectName && !inCatalog ? esc(serviceLinesPreview(preselectName)) : ''}</div>
                        </div>
                        <div id="jc-line-alert-${idx}"></div>
                        <button class="btn btn-danger btn-xs" style="margin-top:8px" onclick="this.closest('.jc-line-row').remove()">Remove</button>
                    </div>`);
                if (inCatalog) {
                    const row = container.lastElementChild;
                    const plate = document.getElementById('jcTruckPlate')?.value;
                    const alertEl = row.querySelector('[id^="jc-line-alert"]');
                    if (alertEl && plate) alertEl.innerHTML = intervalAlertHtml(plate, preselectName);
                }
            }
            function onJcLineServiceChange(sel) {
                const row = sel.closest('.jc-line-row');
                const wrap = row.querySelector('.jc-line-custom-wrap');
                const custom = row.querySelector('.jc-line-custom');
                const alertEl = row.querySelector('[id^="jc-line-alert"]');
                if (sel.value === '__custom__') {
                    if (wrap) wrap.style.display = 'block';
                    custom.value = '';
                    onJcMultilineInput(custom);
                    custom.focus();
                    if (alertEl) alertEl.innerHTML = '';
                    return;
                }
                if (wrap) wrap.style.display = 'none';
                const plate = document.getElementById('jcTruckPlate')?.value;
                if (alertEl && plate && sel.value) alertEl.innerHTML = intervalAlertHtml(plate, sel.value);
            }
            // ── Several services typed in one box (Oct 2026) ──
            // A custom service box takes one service per line: Enter starts the next one. Numbering or a bullet
            // at the start ("1.", "2)", "-", "•") is taken off, a trailing comma too, blank lines are skipped,
            // and commas INSIDE a line stay ("Gasket cover Room 1,2,3,4,5,6" is one job). A number written as
            // part of the text ("1.5 L oil top-up") is kept: only a number followed by "." or ")" and then
            // something other than a digit counts as numbering.
            function splitServiceLines(text) {
                const out = [];
                const seen = new Set();
                String(text == null ? '' : text).split(/\r?\n/).forEach(raw => {
                    let line = String(raw)
                        .replace(/^\s*\(?\d{1,3}[.)](?!\d)\s*/, '')
                        .replace(/^\s*[-•*·]\s+/, '')
                        .replace(/[\s,;]+$/, '')
                        .replace(/\s{2,}/g, ' ')
                        .trim();
                    if (!line) return;
                    const key = line.toLowerCase();
                    if (seen.has(key)) return;
                    seen.add(key);
                    out.push(line);
                });
                return out;
            }
            // A typed line that names a catalogue service is saved as that service, so its interval
            // reminders and service history keep working.
            function catalogServiceName(name) {
                const hit = getServiceCatalog().find(s => String(s.name || '').trim().toLowerCase() === String(name).trim().toLowerCase());
                return hit ? hit.name : name;
            }
            function serviceLinesPreview(text) {
                const lines = splitServiceLines(text).map(catalogServiceName);
                if (!lines.length) return '';
                return `${lines.length} service${lines.length === 1 ? '' : 's'}: ${lines.join(' · ')}`;
            }
            function onJcMultilineInput(el) {
                if (!el) return;
                const preview = el.parentElement && el.parentElement.querySelector('.jc-multiline-preview');
                if (preview) preview.textContent = serviceLinesPreview(el.value);
            }
            function collectDriverLinesFromForm() {
                const lines = [];
                const seen = new Set();
                const add = name => {
                    const key = String(name).trim().toLowerCase();
                    if (!key || seen.has(key)) return; // the same service twice is one job, not two ticks
                    seen.add(key);
                    lines.push({ lineId: newLineId(), serviceKey: normalizeServiceKey(name), name, notes: '' });
                };
                document.querySelectorAll('#jcServicesContainer .jc-line-row').forEach(row => {
                    const sel = row.querySelector('.jc-line-service');
                    if (!sel || !sel.value) return;
                    if (sel.value === '__custom__') {
                        splitServiceLines(row.querySelector('.jc-line-custom')?.value).forEach(n => add(catalogServiceName(n)));
                    } else {
                        add(sel.value);
                    }
                });
                return lines;
            }
            let _jcSaving = false;
            // A typed date in the future is refused here too: the date box's max is only a hint to the picker.
            function jcDateProblem(date) {
                if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return 'Enter the job card date';
                if (date > todayYMD()) return 'The job card date cannot be in the future';
                return '';
            }
            async function saveJobCard(andSubmit) {
                if (_jcSaving) return;
                _jcSaving = true;
                try { await saveJobCardNow(andSubmit); } finally { _jcSaving = false; }
            }
            async function saveJobCardNow(andSubmit) {
                const plate = (document.getElementById('jcTruckPlate')?.value || '').trim().toUpperCase();
                const driver = (document.getElementById('jcDriver')?.value || '').trim();
                const priority = document.querySelector('input[name="jcPriority"]:checked')?.value || 'Medium';
                const date = (document.getElementById('jcDate')?.value || '').trim() || todayYMD();
                const odometer = (document.getElementById('jcOdometer')?.value || '').trim();
                const driverLines = collectDriverLinesFromForm();
                if (!plate || !driver || !driverLines.length) {
                    showToast('Fill truck plate, driver name, and at least one service');
                    return;
                }
                if (jcDateProblem(date)) { showToast(jcDateProblem(date)); return; }
                if (getActiveJobCardForTruck(plate)) {
                    showToast('Truck already has an open job card');
                    return;
                }
                const jc = {
                    id: newJobCardId(),
                    date,
                    odometer,
                    plate, driver, priority,
                    status: 'Draft',
                    driverLines,
                    mechanicLines: driverLines.map(dl => ({
                        driverLineId: dl.lineId,
                        done: false,
                        actualHours: 0,
                        partsCost: 0,
                        labourCost: 0,
                        actualCost: 0,
                        mechanic: '',
                        completedAt: null,
                        notDoneReason: '',
                        unplanned: false
                    })),
                    auditLog: [],
                    createdBy: getCurrentUserLabel(),
                    createdAt: new Date().toISOString()
                };
                const draftFileInput = document.getElementById('jcDraftProofFile');
                if (draftFileInput && draftFileInput.files && draftFileInput.files[0]) {
                    showToast('Processing handwritten proof…');
                    const proofObj = await validateAndReadProof(draftFileInput.files[0], jc.id + '-handwritten');
                    if (proofObj) {
                        jc.handwrittenProof = await storeProofFile(jc, proofObj);
                    }
                }
                addAuditLog(jc, getFgRole(), 'created', driverLines.map(l => l.name).join(', ') + ` · Date: ${date}${odometer ? ' · Odo: ' + odometer : ''}`);
                jobCards.push(jc);
                logAudit('jobcard.create', 'jobCard', jc.id, `${plate} · ${driverLines.length} line(s) · Date: ${date}`);
                saveAll(['jobCards', 'auditTrail']);
                if (andSubmit) {
                    submitJobCardToMechanic(jc.id);
                    return;
                }
                closeModal();
                renderJobCardsPage();
                showToast(`Job card ${jc.id} created`);
            }
            function ensureMechanicLines(jc) {
                (jc.driverLines || []).forEach(dl => {
                    if (!(jc.mechanicLines || []).some(m => m.driverLineId === dl.lineId)) {
                        jc.mechanicLines.push({
                            driverLineId: dl.lineId, done: false, actualHours: 0, partsCost: 0, labourCost: 0,
                            actualCost: 0, mechanic: '', completedAt: null, notDoneReason: '', unplanned: false
                        });
                    }
                });
            }
            // ═══════════ Handwritten Proof Helpers ═══════════
            /**
             * Compress an image file using the Canvas API.
             * Targets ≤300 KB. Returns a {data, size, type} object.
             */
            // compressImageFile() is defined once, in the attachments section (audit X10).
            /**
             * Read a PDF file as base64 data URL.
             * Warns if >2 MB but still allows it.
             */
            function readPdfFile(file) {
                return new Promise((resolve, reject) => {
                    const MAX_PDF = 2 * 1024 * 1024; // 2 MB
                    if (file.size > MAX_PDF) {
                        showToast('⚠️ PDF is large (' + (file.size / 1024 / 1024).toFixed(1) + ' MB). Consider compressing it for better performance.');
                    }
                    const reader = new FileReader();
                    reader.onload = (e) => resolve({ data: e.target.result, size: file.size, type: 'application/pdf' });
                    reader.onerror = reject;
                    reader.readAsDataURL(file);
                });
            }

            /** Format bytes into a human-readable string */
            function fmtBytes(bytes) {
                if (bytes < 1024) return bytes + ' B';
                if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
                return (bytes / 1024 / 1024).toFixed(2) + ' MB';
            }

            /**
             * Validate, compress (if image), and read the file.
             * Returns a proof object: { name, type, data, size, uploadedAt }
             */
            async function validateAndReadProof(file, customName) {
                const allowed = ['image/jpeg', 'image/png', 'image/jpg', 'application/pdf'];
                if (!allowed.includes(file.type) && !file.name.match(/\.(pdf|png|jpg|jpeg)$/i)) {
                    showToast('Please upload a PDF, PNG, or JPG file');
                    return null;
                }
                const isPdf = file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf');
                const ext = isPdf ? '.pdf' : (file.type === 'image/png' ? '.png' : '.jpg');
                const finalName = (customName && customName.trim()) ? customName.trim() + ext : file.name;
                try {
                    let fileData, fileSize, fileType;
                    if (isPdf) {
                        const pdfRes = await readPdfFile(file);
                        fileData = pdfRes.data;
                        fileSize = pdfRes.size;
                        fileType = 'application/pdf';
                    } else {
                        const dataUrl = await compressImageFile(file);
                        fileData = dataUrl;
                        fileSize = Math.round(dataUrl.length * 0.75);
                        fileType = file.type || 'image/jpeg';
                    }
                    return {
                        name: finalName,
                        type: fileType,
                        data: fileData,
                        size: fileSize,
                        uploadedAt: todayYMD()
                    };
                } catch (err) {
                    console.error('Proof read error:', err);
                    showToast('Failed to read file. Please try again.');
                    return null;
                }
            }

            // ── Proof storage (audit J10) ─────────────────────────────────────────
            // Preferred record shape: { name, type, mimeType, size, uploadedAt, uploadedBy, driveId, url }.
            // Legacy / offline fallback keeps `data` (base64 data URL) and sets storage:'local'.
            function proofIsPdf(p) { return !!p && (p.type === 'application/pdf' || p.mimeType === 'application/pdf'); }
            function proofDriveId(p) { return p ? (p.driveId || extractDriveFileId(p.url || '')) : ''; }
            function proofViewSrc(p) {
                if (!p) return '';
                if (typeof p.data === 'string' && p.data.startsWith('data:')) return p.data;
                const id = proofDriveId(p);
                if (!id) return p.url || '';
                return proofIsPdf(p) ? `https://drive.google.com/file/d/${id}/preview` : `https://drive.google.com/thumbnail?id=${id}&sz=w1600`;
            }
            function proofDownloadHref(p) {
                if (!p) return '';
                if (typeof p.data === 'string' && p.data.startsWith('data:')) return p.data;
                const id = proofDriveId(p);
                return id ? `https://drive.google.com/uc?export=download&id=${id}` : (p.url || '');
            }
            function driveUploadAvailable() {
                const ep = window.GOOGLE_APPS_SCRIPT_UPLOAD_URL;
                return !!ep && !String(ep).includes('YOUR_SCRIPT_ID') && navigator.onLine !== false;
            }
            async function storeProofFile(jc, proof) {
                // Never keep base64 in the record when Drive is available; fall back (with a warning) only if the upload fails.
                const rec = { name: proof.name, type: proof.type, mimeType: proof.type, size: proof.size, uploadedAt: todayYMD(), uploadedBy: getCurrentUserLabel() };
                if (driveUploadAvailable()) {
                    try {
                        const safe = String(proof.name || 'proof').replace(/[^a-zA-Z0-9._-]+/g, '_');
                        const res = await uploadToGoogleDrive({ base64: dataUrlToBase64(proof.data), fileName: `${jc.id}-${safe}`, mimeType: proof.type, folder: `fleetguard/jobcards/${jc.id}` });
                        rec.url = res.url; rec.driveId = res.id || extractDriveFileId(res.url) || null; rec.storage = 'drive';
                        return rec;
                    } catch (err) {
                        console.warn('Proof upload to Drive failed, keeping local copy:', err);
                        showToast('⚠ Drive upload failed — proof kept in the database as a local copy. ' + (err.message || ''), 6000);
                    }
                } else {
                    showToast('⚠ Drive upload not available — proof stored in the database (large).', 5000);
                }
                rec.data = proof.data; rec.storage = 'local';
                return rec;
            }

            /** Handle actual file upload after rename confirmation */
            async function uploadHandwrittenProof(jobCardId, input, customName) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                const file = input && input.files && input.files[0];
                if (!file) return;
                const formState = collectMechanicFormState(); // audit J2: keep unsaved mechanic entries
                showToast('Processing file…');
                const proof = await validateAndReadProof(file, customName);
                if (!proof) return;
                const replaced = !!jc.handwrittenProof;
                jc.handwrittenProof = await storeProofFile(jc, proof);
                addAuditLog(jc, getFgRole(), (replaced ? 'replaced' : 'uploaded') + ' handwritten proof', proof.name + (jc.handwrittenProof.storage === 'drive' ? ' (Drive)' : ' (local copy)'));
                logAudit('jobcard.proof', 'jobCard', jc.id, proof.name);
                saveAll(['jobCards', 'auditTrail']);
                delete _jcPendingProofInputs[jobCardId];
                showToast('✅ Proof ' + (replaced ? 'replaced' : 'uploaded') + ' — ' + proof.name + ' (' + fmtBytes(proof.size) + ')');
                if (document.querySelector('#modalBox .preview-grid')) {
                    openJobCardPreview(jobCardId);
                } else {
                    rerenderJobCardModal(jobCardId, formState);
                }
                if (document.getElementById('page-jobcards')?.classList.contains('active')) {
                    renderJcKanban();
                    renderJcHistory();
                }
            }

            // Hidden file inputs created on demand (audit J4 "Replace proof").
            const _jcPendingProofInputs = {};
            function getProofFileInput(jobCardId) {
                return document.getElementById('proofFileInput_' + jobCardId) || _jcPendingProofInputs[jobCardId] || null;
            }
            function replaceHandwrittenProof(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                // From the History list no card is open, and the "name the file" step is drawn INSIDE the
                // open card — so the file was chosen and then nothing happened. Open the card first.
                if (!document.getElementById('modalOverlay')?.classList.contains('open')) openJobCardModal(jobCardId);
                let input = _jcPendingProofInputs[jobCardId];
                if (!input) {
                    input = document.createElement('input');
                    input.type = 'file';
                    input.accept = '.pdf,.png,.jpg,.jpeg';
                    input.style.display = 'none';
                    input.addEventListener('change', () => showProofRenameUi(jobCardId, input));
                    document.body.appendChild(input);
                    _jcPendingProofInputs[jobCardId] = input;
                }
                input.value = '';
                input.click();
            }
            function attachHandwrittenProof(jobCardId) {
                replaceHandwrittenProof(jobCardId);
            }

            /**
             * Show inline rename UI inside the modal before actual upload.
             * Triggered when the user selects a file.
             */
            function showProofRenameUi(jobCardId, inputEl) {
                const file = inputEl.files && inputEl.files[0];
                if (!file) return;
                const isPdf = file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf');
                const ext = isPdf ? '.pdf' : (file.type === 'image/png' ? '.png' : '.jpg');
                const jc = jobCards.find(j => j.id === jobCardId);
                const defaultName = jc ? (jc.id + '-handwritten') : file.name.replace(/\.[^.]+$/, '');
                const existingRow = document.getElementById('proofRenameRow_' + jobCardId);
                if (existingRow) existingRow.remove();
                const zone = document.getElementById('proofUploadZone_' + jobCardId) ||
                             document.getElementById('proofAttachBox_' + jobCardId) ||
                             document.querySelector('#modalBox .jc-proof-uploaded') ||
                             document.querySelector('#modalBox .jc-proof-compact') ||
                             document.querySelector('#modalBox .jc-proof-missing') ||
                             document.querySelector('#modalBox .jc-proof-section-title') ||
                             document.querySelector('#modalBox .modal-body');
                if (!zone) return;
                const id = escAttr(jobCardId);
                const row = document.createElement('div');
                row.id = 'proofRenameRow_' + jobCardId;
                row.className = 'jc-rename-row';
                row.innerHTML = `
                    <input type="text" id="proofNameInput_${id}" value="${esc(defaultName)}" placeholder="File name (without extension)" maxlength="80">
                    <span class="ext-badge">${esc(ext)}</span>
                    <span style="font-size:11px;color:var(--text3)">${esc(file.name)} · ${fmtBytes(file.size)}</span>
                    <button class="btn btn-primary btn-sm" onclick="App.confirmProofUpload('${id}')">✅ Upload</button>
                    <button class="btn btn-ghost btn-sm" onclick="App.cancelProofRename('${id}')">Cancel</button>`;
                zone.insertAdjacentElement('afterend', row);
                const nameInput = row.querySelector('input');
                if (nameInput) { nameInput.focus(); nameInput.select(); }
            }

            function confirmProofUpload(jobCardId) {
                const nameInput = document.getElementById('proofNameInput_' + jobCardId);
                const customName = nameInput ? nameInput.value.trim() : '';
                const fileInput = getProofFileInput(jobCardId);
                if (!fileInput || !fileInput.files || !fileInput.files[0]) { showToast('Choose a file first'); return; }
                uploadHandwrittenProof(jobCardId, fileInput, customName);
            }

            function cancelProofRename(jobCardId) {
                const row = document.getElementById('proofRenameRow_' + jobCardId);
                if (row) row.remove();
                const fi = getProofFileInput(jobCardId);
                if (fi) fi.value = '';
            }

            /** Download the stored handwritten proof file */
            function downloadHandwrittenJobCard(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc || !jc.handwrittenProof) {
                    showToast('No handwritten proof attached to this job card');
                    return;
                }
                const p = jc.handwrittenProof;
                const href = proofDownloadHref(p);
                if (!href) { showToast('Proof file is not available'); return; }
                const a = document.createElement('a');
                a.href = href;
                if (href.startsWith('data:')) a.download = p.name || ('handwritten-' + jobCardId + (proofIsPdf(p) ? '.pdf' : '.jpg'));
                else { a.target = '_blank'; a.rel = 'noopener'; }
                document.body.appendChild(a); a.click(); a.remove();
                showToast('Downloading handwritten proof…');
            }

            /** Download both digital PDF and handwritten proof */
            function downloadBothJobCardFiles(jobCardId) {
                downloadJobCardReportById(jobCardId);
                setTimeout(() => downloadHandwrittenJobCard(jobCardId), 600);
            }

            // Audit J3: in-app viewer (iframe for PDF / Drive preview, <img> for images) instead of window.open(dataUrl).
            function viewHandwrittenProof(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc || !jc.handwrittenProof) {
                    showToast('No handwritten proof attached to this job card');
                    return;
                }
                const p = jc.handwrittenProof;
                const src = proofViewSrc(p);
                if (!src) { showToast('Proof file is not available'); return; }
                const isPdf = proofIsPdf(p);
                const driveId = proofDriveId(p);
                const body = isPdf || (driveId && !src.startsWith('data:') && src.includes('/preview'))
                    ? `<iframe src="${esc(src)}" title="${esc(p.name || 'Handwritten proof')}" style="width:100%;height:70vh;border:none;border-radius:12px;background:#fff"></iframe>`
                    : `<div style="max-height:70vh;overflow:auto;border-radius:12px;background:#fff;text-align:center"><img src="${esc(src)}" alt="Handwritten job card proof" style="max-width:100%;display:block;margin:0 auto"></div>`;
                const id = escAttr(jc.id);
                pushModal(`
                    <div class="modal-header">
                        <div><div class="modal-name">📋 Handwritten Proof — ${esc(jc.id)}</div><div class="modal-sub">${formatTruckLabelFromPlate(jc.plate)} · ${esc(jc.driver || '')} · ${esc(p.name || '')} · ${fmtBytes(p.size || 0)}${p.storage === 'local' ? ' · <span style="color:var(--amber)">local copy</span>' : ''}</div></div>
                        <div class="modal-close" onclick="App.closeModal()">✕</div>
                    </div>
                    <div class="modal-body">${body}</div>
                    <div class="modal-actions">
                        ${driveId ? `<a class="btn btn-ghost btn-sm" href="https://drive.google.com/file/d/${esc(driveId)}/view" target="_blank" rel="noopener">👁 Open in Drive</a>` : ''}
                        <button class="btn btn-ghost btn-sm" onclick="App.downloadHandwrittenJobCard('${id}')">⬇ Download</button>
                        <button class="btn btn-ghost" onclick="App.closeModal()">Back</button>
                    </div>`);
            }

            // ── Mechanic work modal ───────────────────────────────────────────────
            // Audit J2: snapshot every editable field so a re-render (add/remove line, proof upload) keeps unsaved entries.
            function collectMechanicFormState() {
                const state = {};
                document.querySelectorAll('#jcMechForm .jc-line-row, #jcMechForm .jc-extra-row').forEach(row => {
                    const key = row.dataset.line || row.dataset.extraId;
                    if (!key) return;
                    state[key] = {
                        done: !!row.querySelector('.jc-m-done')?.checked,
                        parts: row.querySelector('.jc-m-parts')?.value ?? '',
                        labour: row.querySelector('.jc-m-labour')?.value ?? '',
                        mech: row.querySelector('.jc-m-mech')?.value ?? '',
                        reason: row.querySelector('.jc-m-reason')?.value ?? '',
                        name: row.querySelector('.jc-extra-name')?.value ?? ''
                    };
                });
                return state;
            }
            function restoreMechanicFormState(state) {
                if (!state) return;
                Object.keys(state).forEach(key => {
                    const row = document.querySelector(`#jcMechForm [data-line="${CSS.escape(key)}"], #jcMechForm [data-extra-id="${CSS.escape(key)}"]`);
                    if (!row) return;
                    const v = state[key];
                    const set = (sel, val) => { const el = row.querySelector(sel); if (el && val !== undefined) el.value = val; };
                    const d = row.querySelector('.jc-m-done'); if (d) { d.checked = v.done; onJcDoneToggle(d); }
                    set('.jc-m-parts', v.parts); set('.jc-m-labour', v.labour);
                    set('.jc-m-mech', v.mech); set('.jc-m-reason', v.reason);
                    if (row.querySelector('.jc-extra-name')) set('.jc-extra-name', v.name);
                });
            }
            function jobCardModalHtml(jc) {
                const role = getFgRole();
                const id = escAttr(jc.id);
                const canMechanic = canActAsMechanic(role) && jc.status === 'In-Progress';
                const defaultMech = '';

                const driverHtml = (jc.driverLines || []).map(dl => `
                    <div style="padding:12px;background:var(--bg4);border-radius:var(--radius);margin-bottom:10px">
                        <strong>${esc(dl.name)}</strong>
                        ${dl.notes ? `<div style="font-size:11px;color:var(--text3);margin-top:4px">${esc(dl.notes)}</div>` : ''}
                        ${jc.plate ? intervalAlertHtml(jc.plate, dl.name, jc.id, jcPriorCutoff(jc, dl.name)) : ''}
                    </div>`).join('');

                let mechanicHtml = '';
                if (jc.status !== 'Draft') {
                    const mechRow = (m, label, lineId, isExtra) => {
                        const hist = !isExtra ? findLastServiceFromHistory(jc.plate, label, jc.id, jcPriorCutoff(jc, label)) : null;
                        const histNote = hist ? `<div style="font-size:10px;color:var(--text3);margin-top:4px">Prior: ${esc(hist.date)}${hist.jobCardId ? ' · ' + esc(hist.jobCardId) : ''}</div>` : '';
                        if (canMechanic) {
                            const rowCls = isExtra ? 'jc-extra-row' : 'jc-line-row';
                            const dataAttr = isExtra ? `data-extra-id="${esc(lineId)}"` : `data-line="${esc(lineId)}"`;
                            // Extra work takes several jobs too, one per line; on Save each extra line becomes its own row to tick.
                            const nameField = isExtra ? `<div class="jc-extra-name-wrap"><textarea class="jc-extra-name jc-multiline" rows="2" placeholder="Describe extra work — one job per line, Enter for the next" oninput="App.onJcMultilineInput(this)" style="border-color:var(--teal)">${esc(m.name || '')}</textarea><div class="jc-multiline-preview"></div></div>` : `<div style="font-weight:600;margin-bottom:8px">${esc(label)}</div>`;
                            return `<div class="${rowCls}" ${dataAttr}>
                                ${isExtra ? '<div style="font-size:10px;color:var(--teal);margin-bottom:4px">Extra work (not on job card)</div>' : ''}
                                ${nameField}${histNote}
                                <label style="display:flex;align-items:center;gap:8px;margin-bottom:8px;font-size:12px">
                                    <input type="checkbox" class="jc-m-done" ${m.done ? 'checked' : ''} onchange="App.onJcDoneToggle(this)"> Completed
                                </label>
                                <div class="info-grid" style="grid-template-columns:1fr 1fr 1fr">
                                    <input type="number" class="jc-m-parts" value="${m.partsCost || ''}" placeholder="Parts (RWF)" step="1" min="0" style="padding:8px;background:var(--bg3);border:1px solid var(--border);border-radius:var(--radius);color:var(--text)">
                                    <input type="number" class="jc-m-labour" value="${m.labourCost || ''}" placeholder="Labour (RWF)" step="1" min="0" style="padding:8px;background:var(--bg3);border:1px solid var(--border);border-radius:var(--radius);color:var(--text)">
                                    <input type="text" class="jc-m-mech" value="${esc(jcPersonName(m.mechanic) || defaultMech)}" placeholder="Mechanic name" style="padding:8px;background:var(--bg3);border:1px solid var(--border);border-radius:var(--radius);color:var(--text)">
                                </div>
                                ${jcNoteBoxHtml(m)}
                                ${isExtra ? `<button class="btn btn-danger btn-xs" style="margin-top:8px" onclick="App.removeMechanicExtraLine('${id}','${escAttr(lineId)}')">Remove extra</button>` : ''}
                            </div>`;
                        }
                        return `<div style="padding:10px;background:var(--bg3);border-radius:var(--radius);margin-bottom:8px;border:1px solid ${isExtra ? 'var(--teal)' : 'var(--border)'}">
                            <strong>${esc(label)}</strong>${isExtra ? ' <span style="color:var(--teal);font-size:10px">(extra)</span>' : ''} — ${m.done ? '✅' : '⏳'}
                            ${m.done ? `<div style="font-size:11px;margin-top:4px">${formatRwf(m.actualCost)}${jcPersonName(m.mechanic) ? ' · ' + esc(jcPersonName(m.mechanic)) : ''}</div>${m.comment ? `<div style="font-size:11px;color:var(--text2);margin-top:2px">💬 ${esc(m.comment)}</div>` : ''}` : (m.notDoneReason ? `<div style="font-size:11px;color:var(--amber)">${esc(m.notDoneReason)}</div>` : '')}
                            ${histNote}
                        </div>`;
                    };
                    mechanicHtml = (jc.driverLines || []).map(dl => {
                        const m = (jc.mechanicLines || []).find(x => x.driverLineId === dl.lineId && !x.unplanned) || {};
                        return mechRow(m, dl.name, dl.lineId, false);
                    }).join('');
                    mechanicHtml += (jc.mechanicLines || []).filter(m => m.unplanned).map(m =>
                        mechRow(m, m.name || 'Extra work', m.driverLineId, true)
                    ).join('');
                    if (canMechanic) {
                        mechanicHtml += `<button class="btn btn-ghost btn-sm" style="margin-top:12px" onclick="App.addMechanicExtraLine('${id}')">+ Add work not on job card</button>`;
                    }
                }

                // Handwritten proof section: upload/replace for all stages (driver, mechanic, supervisor, or approved).
                let proofSectionHtml = '';
                const proof = jc.handwrittenProof;
                if (canMechanic) {
                    const proofIcon = proof ? (proofIsPdf(proof) ? '📄' : '🖼️') : '📋';
                    const proofContent = proof
                        ? `<div class="jc-proof-uploaded">
                               <span class="proof-icon">${proofIcon}</span>
                               <div class="proof-info">
                                   <div class="proof-name">✅ ${esc(proof.name)}</div>
                                   <div class="proof-meta">${fmtBytes(proof.size || 0)}${proof.storage === 'local' ? ' · <span style="color:var(--amber)">local copy (not on Drive)</span>' : proof.driveId || proof.url ? ' · Drive' : ''}</div>
                               </div>
                               <div class="proof-actions">
                                   <button class="btn btn-ghost btn-xs" onclick="App.viewHandwrittenProof('${id}')">👁 View</button>
                                   <button class="btn btn-ghost btn-xs" style="color:var(--amber)" onclick="App.replaceHandwrittenProof('${id}')">↺ Replace</button>
                               </div>
                           </div>`
                        : `<div class="jc-proof-upload-zone" id="proofUploadZone_${id}" onclick="document.getElementById('proofFileInput_${id}').click()">
                               <span class="upload-icon">📋</span>
                               <div class="upload-label">Upload Handwritten Job Card (Optional)</div>
                               <div class="upload-hint">PDF, PNG, or JPG · Images auto-compressed · Stored on Google Drive</div>
                           </div>`;
                    proofSectionHtml = `
                        <div class="jc-proof-section">
                            <div class="jc-proof-section-title">
                                📋 Handwritten Proof
                                <span class="proof-badge" style="background:var(--bg4);color:var(--text3)">${proof ? 'ATTACHED' : 'OPTIONAL'}</span>
                            </div>
                            ${proofContent}
                            <input type="file" id="proofFileInput_${id}" accept=".pdf,.png,.jpg,.jpeg" style="display:none"
                                   onchange="App.showProofRenameUi('${id}', this)">
                        </div>`;
                } else {
                    proofSectionHtml = `
                        <div class="jc-proof-section">
                            <div class="jc-proof-section-title">
                                📋 Handwritten Proof
                                <span class="proof-badge" style="background:var(--bg4);color:var(--text3)">${proof ? 'ATTACHED' : 'OPTIONAL'}</span>
                            </div>
                            ${proof ? `
                                <div class="jc-proof-uploaded">
                                    <span class="proof-icon">${proofIsPdf(proof) ? '📄' : '🖼️'}</span>
                                    <div class="proof-info">
                                        <div class="proof-name">✅ ${esc(proof.name)}</div>
                                        <div class="proof-meta">${fmtBytes(proof.size || 0)}${proof.storage === 'local' ? ' · <span style="color:var(--amber)">local copy</span>' : ''}</div>
                                    </div>
                                    <div class="proof-actions">
                                        <button class="btn btn-ghost btn-xs" onclick="App.viewHandwrittenProof('${id}')">👁 View</button>
                                        <button class="btn btn-ghost btn-xs" style="color:var(--amber)" onclick="App.replaceHandwrittenProof('${id}')">↺ Replace</button>
                                    </div>
                                </div>` : `
                                <div class="jc-proof-upload-zone" id="proofUploadZone_${id}" onclick="document.getElementById('proofFileInput_${id}').click()">
                                    <span class="upload-icon">📋</span>
                                    <div class="upload-label">Attach Handwritten Job Card (Optional)</div>
                                    <div class="upload-hint">Upload handwritten proof at this stage (PDF, PNG, or JPG)</div>
                                </div>`}
                            <input type="file" id="proofFileInput_${id}" accept=".pdf,.png,.jpg,.jpeg" style="display:none"
                                   onchange="App.showProofRenameUi('${id}', this)">
                        </div>`;
                }

                let actions = `<button class="btn btn-ghost" onclick="App.closeModal()">Close</button>`;
                if (canMechanic) actions += `<button class="btn btn-primary" onclick="App.saveMechanicWork('${id}')">Save work</button>
                    <button class="btn btn-primary" onclick="App.submitJobCardForApproval('${id}')">Submit for approval</button>`;
                if (isSupervisorRole(role) && jc.status === 'Pending-Approval') {
                    actions += `<button class="btn btn-primary" onclick="App.openJobCardPreview('${id}')">Open review</button>`;
                }
                if (jc.status === 'Released') {
                    actions += `<button class="btn btn-ghost" onclick="App.generateJobCardReportById('${id}')">Print report</button>`;
                }
                const meta = [
                    jc.rejectionReason ? `<span style="color:var(--amber)">Last rejection: ${esc(jc.rejectionReason)}</span>` : ''
                ].filter(Boolean).join(' · ');

                return `
                    <div class="modal-header">
                        <div><div class="modal-name">${esc(jc.id)}</div><div class="modal-sub">${formatTruckLabelFromPlate(jc.plate)} · ${esc(jc.driver)} · ${esc(jc.status)}${jc.date ? ' · 📅 ' + esc(jc.date) : ''}${jc.odometer ? ' · ⏱ ' + esc(formatOdometer(jc.odometer)) : ''}${jc.priority ? ' · ' + esc(jc.priority) + ' priority' : ''}</div></div>
                        <div class="modal-close" onclick="App.closeModal()">✕</div>
                    </div>
                    <div class="modal-body">
                        ${meta ? `<div style="font-size:11px;color:var(--text3);margin-bottom:10px">${meta}</div>` : ''}
                        <div class="section"><div class="section-title">Driver request (initial)</div>${driverHtml || '<p style="color:var(--text3)">No lines</p>'}</div>
                        ${jc.status !== 'Draft' ? `<div class="section"><div class="section-title">Mechanic completion (final)</div><div id="jcMechForm">${mechanicHtml}</div></div>` : ''}
                        ${proofSectionHtml}
                    </div>
                    <div class="modal-actions">${actions}</div>`;
            }
            function openJobCardModal(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                if (canActAsDriver() && jc.status === 'Draft') {
                    openEditJobCardModal(jobCardId);
                    return;
                }
                migrateJobCard(jc);
                ensureMechanicLines(jc);
                openModal(jobCardModalHtml(jc));
            }
            // Re-render the open job card modal in place (no stack growth) and restore unsaved form entries.
            function rerenderJobCardModal(jobCardId, formState) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                migrateJobCard(jc);
                ensureMechanicLines(jc);
                replaceModal(jobCardModalHtml(jc));
                restoreMechanicFormState(formState);
            }
            function syncMechCost(checkbox) {
                const row = checkbox.closest('.jc-line-row');
                const parts = parseFloat(row.querySelector('.jc-m-parts')?.value) || 0;
                const labour = parseFloat(row.querySelector('.jc-m-labour')?.value) || 0;
                /* total shown on save */
            }
            // Oct 2026: one box per service — a comment once "Completed" is ticked, the reason when it is not.
            function jcNoteBoxHtml(m) {
                const done = !!m.done, val = done ? (m.comment || '') : (m.notDoneReason || '');
                return `<div class="jc-note-wrap"><div class="jc-note-label" style="font-size:10.5px;margin-top:8px;color:${done ? 'var(--text3)' : 'var(--amber)'}">${done ? '💬 Comment (optional)' : '⚠ Reason not done'}</div>
                    <input type="text" class="jc-m-reason" value="${esc(val)}" placeholder="${done ? 'Comment on this work, e.g. used OEM pads' : 'If not done, reason'}" style="width:100%;margin-top:4px;padding:8px;background:var(--bg3);border:1px solid var(--border);border-radius:var(--radius);color:var(--text);font-size:12px"></div>`;
            }
            function onJcDoneToggle(cb) {
                const row = cb.closest('.jc-line-row, .jc-extra-row'); if (!row) return;
                const lab = row.querySelector('.jc-note-label'), box = row.querySelector('.jc-m-reason');
                if (lab) { lab.textContent = cb.checked ? '💬 Comment (optional)' : '⚠ Reason not done'; lab.style.color = cb.checked ? 'var(--text3)' : 'var(--amber)'; }
                if (box) box.placeholder = cb.checked ? 'Comment on this work, e.g. used OEM pads' : 'If not done, reason';
            }
            function applyMechRowFromDom(row, m) {
                m.done = row.querySelector('.jc-m-done')?.checked || false;
                m.actualHours = m.actualHours || 0; // the hours box is gone; keep what older cards recorded
                m.partsCost = parseFloat(row.querySelector('.jc-m-parts')?.value) || 0;
                m.labourCost = parseFloat(row.querySelector('.jc-m-labour')?.value) || 0;
                m.actualCost = m.partsCost + m.labourCost;
                m.mechanic = row.querySelector('.jc-m-mech')?.value?.trim() || ''; // a typed name only — never the signed-in e-mail
                const note = row.querySelector('.jc-m-reason')?.value?.trim() || '';
                m.comment = m.done ? note : '';
                m.notDoneReason = m.done ? '' : note;
                if (m.unplanned) m.name = row.querySelector('.jc-extra-name')?.value?.trim() || m.name || '';
                if (m.done && !m.completedAt) m.completedAt = todayYMD();
                if (!m.done) m.completedAt = null;
            }
            function saveMechanicWorkFromDom(jc) {
                document.querySelectorAll('#jcMechForm .jc-line-row').forEach(row => {
                    const lineId = row.dataset.line;
                    const m = jc.mechanicLines.find(x => x.driverLineId === lineId && !x.unplanned);
                    if (!m) return;
                    applyMechRowFromDom(row, m);
                });
                // An extra-work box holding several lines becomes several extra jobs: the first keeps the tick and
                // the costs typed on that row; each further line is added right after it, unticked, to be done
                // and priced on its own. Returns how many rows were added so the caller can show them.
                let added = 0;
                document.querySelectorAll('#jcMechForm .jc-extra-row').forEach(row => {
                    const lineId = row.dataset.extraId;
                    const m = jc.mechanicLines.find(x => x.driverLineId === lineId && x.unplanned);
                    if (!m) return;
                    applyMechRowFromDom(row, m);
                    const parts = splitServiceLines(row.querySelector('.jc-extra-name')?.value);
                    if (parts.length <= 1) { m.name = parts[0] || ''; return; }
                    m.name = parts[0];
                    const at = jc.mechanicLines.indexOf(m);
                    const extra = parts.slice(1).map(name => ({
                        driverLineId: newLineId(), unplanned: true, name, done: false, actualHours: 0,
                        partsCost: 0, labourCost: 0, actualCost: 0, mechanic: '', completedAt: null, notDoneReason: ''
                    }));
                    jc.mechanicLines.splice(at + 1, 0, ...extra);
                    added += extra.length;
                });
                return added;
            }
            function addMechanicExtraLine(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc || jc.status !== 'In-Progress') return;
                const formState = collectMechanicFormState();
                jc.mechanicLines.push({
                    driverLineId: newLineId(),
                    unplanned: true,
                    name: '',
                    done: false,
                    actualHours: 0,
                    partsCost: 0,
                    labourCost: 0,
                    actualCost: 0,
                    mechanic: '',
                    completedAt: null,
                    notDoneReason: ''
                });
                saveAll(['jobCards']);
                rerenderJobCardModal(jobCardId, formState);
                const rows = document.querySelectorAll('#jcMechForm .jc-extra-row');
                const last = rows[rows.length - 1];
                if (last) { last.scrollIntoView({ behavior: 'smooth', block: 'center' }); last.querySelector('.jc-extra-name')?.focus(); }
            }
            function removeMechanicExtraLine(jobCardId, lineId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                const formState = collectMechanicFormState();
                delete formState[lineId];
                jc.mechanicLines = jc.mechanicLines.filter(m => !(m.unplanned && m.driverLineId === lineId));
                saveAll(['jobCards']);
                rerenderJobCardModal(jobCardId, formState);
            }
            function saveMechanicWork(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                if (!canActAsMechanic()) {
                    showToast('Only mechanics can enter prices and values');
                    return;
                }
                const split = saveMechanicWorkFromDom(jc);
                addAuditLog(jc, getFgRole(), 'saved work', `${jc.mechanicLines.filter(m => m.done).length}/${jc.mechanicLines.length} lines done · ${formatRwf(jcTotals(jc).actC)}`);
                logAudit('jobcard.work', 'jobCard', jc.id, 'mechanic work saved');
                saveAll(['jobCards', 'auditTrail']);
                rerenderJobCardModal(jobCardId);
                showToast(split ? `Work saved — extra work split into separate jobs (${split} added); tick and price each one` : 'Work saved', split ? 5000 : 2800);
            }
            function mechanicLinesComplete(jc) {
                const driverOk = (jc.driverLines || []).every(dl => {
                    const m = (jc.mechanicLines || []).find(x => x.driverLineId === dl.lineId && !x.unplanned);
                    if (!m) return false;
                    return m.done || (m.notDoneReason && m.notDoneReason.trim());
                });
                const extrasOk = (jc.mechanicLines || []).filter(m => m.unplanned).every(m => {
                    if (!m.done) return true;
                    return !!(m.name && m.name.trim());
                });
                return driverOk && extrasOk;
            }
            function submitJobCardToMechanic(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                jc.status = 'In-Progress';
                jc.submittedAt = new Date().toISOString();
                addAuditLog(jc, getFgRole(), 'submitted to garage');
                setTruckGarageStatus(jc.plate, true);
                logAudit('jobcard.submit', 'jobCard', jc.id, `${jc.plate} sent to garage`);
                saveAll(['jobCards', 'trucks', 'auditTrail']);
                closeModal();
                renderJobCardsPage();
                showToast('Submitted to mechanics — truck in garage');
            }
            function submitJobCardForApproval(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                if (!canActAsMechanic()) {
                    showToast('Only mechanics can submit work for approval');
                    return;
                }
                // Extra work typed as several lines has just become several new, unticked jobs: stop and show
                // them, rather than send the card on before the mechanic has ticked and priced each one.
                const split = saveMechanicWorkFromDom(jc);
                if (split) {
                    saveAll(['jobCards']);
                    rerenderJobCardModal(jobCardId);
                    showToast(`Extra work split into separate jobs (${split} added) — tick and price each one, then submit again`, 6000);
                    return;
                }
                if (!mechanicLinesComplete(jc)) {
                    showToast('Complete or explain every service line');
                    return;
                }
                const doneCount = jc.mechanicLines.filter(m => m.done).length;
                if (!doneCount) {
                    showToast('Mark at least one service as completed');
                    return;
                }
                jc.status = 'Pending-Approval';
                jc.completedAt = new Date().toISOString();
                jc.completedBy = getCurrentUserLabel();
                addAuditLog(jc, getFgRole(), 'submitted for approval', formatRwf(jcTotals(jc).actC));
                logAudit('jobcard.submit-approval', 'jobCard', jc.id, formatRwf(jcTotals(jc).actC));
                saveAll(['jobCards', 'auditTrail']);
                closeModal();
                renderJobCardsPage();
                showToast('Sent to supervisor for approval');
            }
            function generateJobCardReportById(id) {
                const jc = jobCards.find(j => j.id === id);
                if (jc) generateJobCardReport(jc);
            }
            function downloadJobCardReportById(id) {
                const jc = jobCards.find(j => j.id === id);
                if (!jc) return;
                const html = generateJobCardReportHtml(jc);
                downloadHtmlAsPdf(html, `jobcard-${jc.id}.pdf`);
            }
            // Resolves once the PDF has really been saved; the toast says so only then.
            const JC_PDF_CSS = '.jc-print-card{min-height:1060px}';
            async function downloadHtmlAsPdf(html, filename) {
                try {
                    const res = await buildPdfDocument([html], filename, JC_PDF_CSS, 'Building job card PDF');
                    showToast(`PDF downloaded ✓ (${res.pages} page${res.pages === 1 ? '' : 's'})`);
                    return true;
                } catch (err) {
                    console.error('PDF failed:', err);
                    showToast('Could not build the PDF — ' + ((err && err.message) || 'unknown error') + '. Use Print → Save as PDF instead.', 6000);
                    return false;
                }
            }
            async function downloadHtmlAsPdfBlob(html) {
                await loadHtml2Pdf();
                return html2pdf().set(PDF_OPTIONS).from(await embedImagesForPdf(`<style>${JC_PDF_CSS}</style>` + html)).outputPdf('blob');
            }
            let _pdfLibLoadingPromise = null;
            function loadPdfLib() {
                if (window.PDFLib) return Promise.resolve(window.PDFLib);
                if (_pdfLibLoadingPromise) return _pdfLibLoadingPromise;
                _pdfLibLoadingPromise = new Promise((resolve, reject) => {
                    const script = document.createElement('script');
                    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.17.1/pdf-lib.min.js';
                    script.onload = () => resolve(window.PDFLib);
                    script.onerror = () => { _pdfLibLoadingPromise = null; script.remove(); reject(new Error('PDF library could not be loaded (offline or blocked)')); };
                    document.head.appendChild(script);
                });
                return _pdfLibLoadingPromise;
            }
            // Print windows used to call print() straight after writing the page, before the logo had
            // loaded, so the letterhead printed without it. Wait for every image first (max 5 s).
            function printWhenReady(win) {
                const go = () => { try { win.focus(); win.print(); } catch (e) { /* window closed */ } };
                try {
                    const imgs = [...win.document.images].filter(i => !i.complete);
                    if (!imgs.length) { setTimeout(go, 150); return; }
                    let left = imgs.length, done = false;
                    const one = () => { if (!done && --left <= 0) { done = true; go(); } };
                    imgs.forEach(i => { i.addEventListener('load', one); i.addEventListener('error', one); });
                    setTimeout(() => { if (!done) { done = true; go(); } }, 5000);
                } catch (e) { setTimeout(go, 400); }
            }
            function dataUrlToBlob(dataUrl) {
                const parts = dataUrl.split(',');
                const mimeMatch = parts[0].match(/:(.*?);/);
                const mime = mimeMatch ? mimeMatch[1] : 'application/octet-stream';
                const byteString = atob(parts[1]);
                const array = new Uint8Array(byteString.length);
                for (let i = 0; i < byteString.length; i++) array[i] = byteString.charCodeAt(i);
                return new Blob([array], { type: mime });
            }
            async function mergePdfBlobs(blobA, blobB) {
                await loadPdfLib();
                const arrA = await blobA.arrayBuffer();
                const arrB = await blobB.arrayBuffer();
                const mergedPdf = await PDFLib.PDFDocument.create();
                const pdfA = await PDFLib.PDFDocument.load(arrA);
                const pdfB = await PDFLib.PDFDocument.load(arrB);
                const pagesA = await mergedPdf.copyPages(pdfA, pdfA.getPageIndices());
                pagesA.forEach(page => mergedPdf.addPage(page));
                const pagesB = await mergedPdf.copyPages(pdfB, pdfB.getPageIndices());
                pagesB.forEach(page => mergedPdf.addPage(page));
                const mergedBytes = await mergedPdf.save();
                return new Blob([mergedBytes], { type: 'application/pdf' });
            }
            function openJobCardPreview(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                const isReleased = jc.status === 'Released';
                if (!isReleased && !isSupervisorRole()) {
                    showToast('Supervisor role required');
                    return;
                }
                migrateJobCard(jc);
                const t = jcTotals(jc);
                const id = escAttr(jc.id);

                const driverCol = (jc.driverLines || []).map(dl => `
                    <div class="preview-item">
                        <div class="preview-item-name">${esc(dl.name)}</div>
                        <div style="font-size:10px;color:var(--text3);margin-top:4px">Requested by driver — no pricing</div>
                        ${intervalAlertHtml(jc.plate, dl.name, jc.id, jcPriorCutoff(jc, dl.name))}
                    </div>`).join('');

                const mechCol = (jc.driverLines || []).map(dl => {
                    const m = (jc.mechanicLines || []).find(x => x.driverLineId === dl.lineId && !x.unplanned) || {};
                    return `<div class="preview-item">
                        <div class="preview-item-name">${esc(dl.name)} ${m.done ? '✅' : '—'}</div>
                        <div class="preview-item-details">
                            <div class="preview-detail"><div class="preview-detail-label">Parts</div><div class="preview-detail-value">${formatRwf(m.partsCost || 0)}</div></div>
                            <div class="preview-detail"><div class="preview-detail-label">Labour</div><div class="preview-detail-value">${formatRwf(m.labourCost || 0)}</div></div>
                            <div class="preview-detail"><div class="preview-detail-label">Total</div><div class="preview-detail-value">${formatRwf(m.actualCost || 0)}</div></div>
                        </div>
                        <div style="font-size:10px;color:var(--text3)">${esc(jcPersonName(m.mechanic))}${!m.done && m.notDoneReason ? (jcPersonName(m.mechanic) ? ' · ' : '') + '<span style="color:var(--amber)">Not done: ' + esc(m.notDoneReason) + '</span>' : ''}</div>
                        ${m.done && m.comment ? `<div style="font-size:11px;color:var(--text2);margin-top:3px">💬 ${esc(m.comment)}</div>` : ''}
                    </div>`;
                }).join('') + (jc.mechanicLines || []).filter(m => m.unplanned).map(m => `
                    <div class="preview-item" style="border-left:2px solid var(--teal)">
                        <div class="preview-item-name">${esc(m.name || 'Extra work')} ${m.done ? '✅' : '—'} <span style="color:var(--teal);font-size:9px">EXTRA</span></div>
                        <div class="preview-item-details">
                            <div class="preview-detail"><div class="preview-detail-label">Parts</div><div class="preview-detail-value">${formatRwf(m.partsCost || 0)}</div></div>
                            <div class="preview-detail"><div class="preview-detail-label">Labour</div><div class="preview-detail-value">${formatRwf(m.labourCost || 0)}</div></div>
                            <div class="preview-detail"><div class="preview-detail-label">Total</div><div class="preview-detail-value">${formatRwf(m.actualCost || 0)}</div></div>
                        </div>
                        ${m.done && m.comment ? `<div style="font-size:11px;color:var(--text2);margin-top:3px">💬 ${esc(m.comment)}</div>` : ''}${!m.done && m.notDoneReason ? `<div style="font-size:10px;color:var(--amber)">Not done: ${esc(m.notDoneReason)}</div>` : ''}
                    </div>`).join('');

                // Compact proof badge (no embedded preview — that lives in the combined preview window)
                const proof = jc.handwrittenProof;
                let proofBadgeHtml = '';
                if (proof) {
                    const isPdf = proofIsPdf(proof);
                    const proofIcon = isPdf ? '📄' : '🖼️';
                    proofBadgeHtml = `
                        <div class="jc-proof-compact">
                            <span class="jc-proof-compact-icon">${proofIcon}</span>
                            <div class="jc-proof-compact-info">
                                <div class="jc-proof-compact-name">${esc(proof.name)}</div>
                                <div class="jc-proof-compact-meta">${isPdf ? 'PDF' : 'Image'} &nbsp;·&nbsp; ${fmtBytes(proof.size || 0)}</div>
                            </div>
                            <div style="display:flex;gap:6px;align-items:center">
                                <button class="btn btn-ghost btn-xs" onclick="App.viewHandwrittenProof('${id}')">👁 Full View</button>
                                <button class="btn btn-ghost btn-xs" onclick="App.replaceHandwrittenProof('${id}')">🔄 Replace</button>
                            </div>
                        </div>`;
                } else {
                    proofBadgeHtml = `
                        <div class="jc-proof-compact" style="border-color:var(--border);background:var(--bg2)">
                            <span class="jc-proof-compact-icon">📋</span>
                            <div class="jc-proof-compact-info">
                                <div class="jc-proof-compact-name" style="color:var(--text3)">No handwritten proof attached</div>
                                <div class="jc-proof-compact-meta">Digital card can be approved, or attach handwritten card anytime</div>
                            </div>
                            <button class="btn btn-outline btn-xs" onclick="App.attachHandwrittenProof('${id}')">📎 Attach Handwritten Card</button>
                        </div>`;
                }

                openModal(`
                    <div class="modal-header">
                        <div><div class="modal-name">Review ${jc.id}</div><div class="modal-sub">${formatTruckLabelFromPlate(jc.plate || '')} · ${esc(jc.driver || '')} · Date: ${esc(jc.date || (jc.createdAt ? String(jc.createdAt).slice(0, 10) : '—'))}${jc.odometer ? ' · Odo: ' + esc(formatOdometer(jc.odometer)) : ''}</div></div>
                        <div class="modal-close" onclick="App.closeModal()">✕</div>
                    </div>
                    <div class="modal-body">
                        <div class="preview-grid">
                            <div class="preview-column">
                                <div class="preview-column-title">Initial (Driver)</div>
                                ${driverCol}
                                <div class="preview-summary">
                                    <div class="preview-summary-row"><span class="preview-summary-label">Services</span><span class="preview-summary-value">${(jc.driverLines || []).length}</span></div>
                                    <div class="preview-summary-row"><span class="preview-summary-label">Date created</span><span class="preview-summary-value">${esc(jc.date || (jc.createdAt ? String(jc.createdAt).slice(0, 10) : '—'))}</span></div>
                                    ${jc.odometer ? `<div class="preview-summary-row"><span class="preview-summary-label">Odometer</span><span class="preview-summary-value">${esc(formatOdometer(jc.odometer))}</span></div>` : ''}
                                </div>
                            </div>
                            <div class="preview-column">
                                <div class="preview-column-title">Final (Mechanic)</div>
                                ${mechCol}
                                <div class="preview-summary">
                                    <div class="preview-summary-row"><span class="preview-summary-label">Total parts</span><span class="preview-summary-value">${formatRwf(t.actP)}</span></div>
                                    <div class="preview-summary-row"><span class="preview-summary-label">Total labour</span><span class="preview-summary-value">${formatRwf(t.actL)}</span></div>
                                    <div class="preview-summary-row"><span class="preview-summary-label">Total cost</span><span class="preview-summary-value">${formatRwf(t.actC)}</span></div>
                                </div>
                            </div>
                        </div>
                        ${proofBadgeHtml}
                        ${jc.rejectionReason ? `<div class="jc-interval-alert jc-interval-warn" style="margin-top:12px">Previously rejected: ${esc(jc.rejectionReason)}</div>` : ''}
                    </div>
                    <div class="modal-actions">
                        <button class="btn btn-ghost" onclick="App.closeModal()">Close</button>
                        <div class="modal-dropdown">
                            <button class="btn btn-ghost btn-sm modal-dropdown-toggle" type="button" onclick="App.togglePreviewDropdown(this)">👁 Preview ▾</button>
                            <div class="modal-dropdown-menu">
                                <button type="button" class="dropdown-item" onclick="App.openPreviewChoice('${id}','digital')">Digital job card</button>
                                <button type="button" class="dropdown-item ${proof ? '' : 'disabled'}" onclick="App.openPreviewChoice('${id}','handwritten')">Uploaded proof</button>
                                <button type="button" class="dropdown-item" onclick="App.openPreviewChoice('${id}','combined')">Both combined</button>
                            </div>
                        </div>
                        <div class="modal-dropdown">
                            <button class="btn btn-ghost btn-sm modal-dropdown-toggle" type="button" onclick="App.togglePreviewDropdown(this)">⬇ Download ▾</button>
                            <div class="modal-dropdown-menu">
                                <button type="button" class="dropdown-item" onclick="App.openDownloadChoice('${id}','digital')">Digital job card</button>
                                <button type="button" class="dropdown-item ${proof ? '' : 'disabled'}" onclick="App.openDownloadChoice('${id}','handwritten')">Handwritten proof</button>
                                <button type="button" class="dropdown-item" onclick="App.openDownloadChoice('${id}','combined')">Combined PDF</button>
                            </div>
                        </div>
                        ${isReleased ? '' : `<button class="btn btn-danger" onclick="App.rejectJobCard('${id}')">Reject</button>
                        <button class="btn btn-primary" onclick="App.approveJobCard('${id}')">Approve &amp; release truck</button>`}
                    </div>`);
            }

            /**
             * Opens a new browser tab showing the full digital job card report
             * followed by the full handwritten proof — both fully readable.
             * The supervisor can print (Ctrl+P) this combined view to get a paper copy.
             */
            function openPreviewChoice(jobCardId, type) {
                if (type === 'digital') {
                    App.openDigitalJobCardPreview(jobCardId);
                } else if (type === 'handwritten') {
                    App.viewHandwrittenProof(jobCardId);
                } else if (type === 'combined') {
                    App.openCombinedPreview(jobCardId);
                }
                App.closeDropdownMenus();
            }

            function openDownloadChoice(jobCardId, type) {
                if (type === 'digital') {
                    App.downloadJobCardReportById(jobCardId);
                } else if (type === 'handwritten') {
                    App.downloadHandwrittenJobCard(jobCardId);
                } else if (type === 'combined') {
                    App.downloadCombinedJobCard(jobCardId);
                }
                App.closeDropdownMenus();
            }

            function togglePreviewDropdown(button) {
                const menu = button.nextElementSibling;
                if (!menu) return;
                const shown = menu.style.display === 'flex';
                App.closeDropdownMenus();
                if (shown) return; // was open, now closed — done

                // Measure available space above and below the button
                const rect = button.getBoundingClientRect();
                const spaceBelow = window.innerHeight - rect.bottom;
                const spaceAbove = rect.top;
                const menuHeight = 160; // approx menu height (3 items × ~52px)

                // Choose direction: prefer upward (cleaner for bottom action bars),
                // but fall back to downward if there isn't enough room above
                const goUp = spaceAbove >= menuHeight || spaceAbove >= spaceBelow;
                menu.classList.remove('open-upward', 'open-downward');
                menu.classList.add(goUp ? 'open-upward' : 'open-downward');
                menu.style.display = 'flex';

                // Scroll the button into view so the dropdown is fully visible,
                // but only if the menu would otherwise be clipped
                if (goUp && spaceAbove < menuHeight + 16) {
                    button.scrollIntoView({ behavior: 'smooth', block: 'center' });
                } else if (!goUp && spaceBelow < menuHeight + 16) {
                    button.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }

            function closeDropdownMenus() {
                document.querySelectorAll('.modal-dropdown-menu').forEach(menu => {
                    menu.style.display = 'none';
                    menu.classList.remove('open-upward', 'open-downward');
                });
            }

            function openDigitalJobCardPreview(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Job Card — ${jc.id}</title>
<style>
  body { margin: 0; background: #e2e8f0; font-family: 'Segoe UI', Arial, sans-serif; color: #111; padding: 30px 0; }
  .sheet { max-width: 800px; margin: 0 auto; background: #fff; box-shadow: 0 4px 16px rgba(0,0,0,0.12); position: relative; overflow: hidden; min-height: 1123px; }
  .toolbar { display: flex; flex-wrap: wrap; gap: 10px; max-width: 800px; margin: 0 auto 16px auto; }
  .toolbar button { border: none; background: #c0141c; color: #fff; border-radius: 8px; padding: 10px 20px; font-size: 13px; font-weight: 700; cursor: pointer; letter-spacing: 0.03em; }
  .toolbar button:hover { background: #9b0f15; }
  .sheet .jc-print-card { min-height: 1123px; }
  @page { size: A4; margin: 10mm; }
  @media print {
    body { background: #fff !important; padding: 0 !important; }
    .toolbar { display: none !important; }
    .sheet { box-shadow: none !important; max-width: 100% !important; min-height: auto !important; }
    .sheet .jc-print-card { min-height: 270mm; }
  }
</style>
</head>
<body>
<div class="toolbar"><button onclick="window.print()">🖨 Print</button></div>
<div class="sheet">
  ${generateJobCardReportHtml(jc)}
</div>
</body>
</html>`;
                const win = window.open('', '_blank');
                if (!win) { showToast('Pop-up blocked — please allow pop-ups for this site'); return; }
                win.document.write(html);
                win.document.close();
                try {
                    const printBtn = win.document.querySelector('.toolbar button');
                    if (printBtn) printBtn.onclick = () => win.print();
                } catch (e) { /* cross-origin guard */ }
            }

            function openCombinedPreview(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                const digitalHtml = generateJobCardReportHtml(jc);
                const proof = jc.handwrittenProof;

                let proofSection = '';
                if (proof) {
                    const isPdf = proofIsPdf(proof);
                    const proofSrc = proofViewSrc(proof); // data URL (legacy/local) or Drive preview/thumbnail (audit J10)
                    const proofContent = isPdf || (proofSrc.includes('/preview'))
                        ? `<iframe src="${esc(proofSrc)}" title="Handwritten proof" class="proof-frame"></iframe>`
                        : `<img src="${esc(proofSrc)}" alt="Handwritten job card" class="proof-image">`;
                    proofSection = `
                        <section style="padding:32px 24px;background:#fff;max-width:1100px;margin:24px auto;border-radius:14px;box-shadow:0 16px 40px rgba(0,0,0,0.08)">
                            <header style="display:flex;flex-wrap:wrap;justify-content:space-between;align-items:flex-start;gap:14px;margin-bottom:24px">
                                <div>
                                    <h2 style="margin:0 0 8px;font-size:22px;color:#c62828">Handwritten Job Card Proof</h2>
                                    <p style="margin:0;color:#555;font-size:14px">${xmlEscape(proof.name)} · ${fmtBytes(proof.size)}</p>
                                </div>
                                <div style="text-align:right;color:#666;font-size:13px">${xmlEscape(jc.id)}<br>${formatTruckLabelFromPlate(jc.plate)}</div>
                            </header>
                            <div>${proofContent}</div>
                        </section>`;
                } else {
                    proofSection = `
                        <section style="padding:32px 24px;background:#fff;max-width:1100px;margin:24px auto;border-radius:14px;box-shadow:0 16px 40px rgba(0,0,0,0.08);text-align:center;color:#666">
                            <h2 style="margin:0 0 16px;font-size:20px">No handwritten proof attached</h2>
                            <p style="margin:0;font-size:14px">This job card does not include an uploaded handwritten proof file.</p>
                        </section>`;
                }

                const fullHtml = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Combined Preview — ${xmlEscape(jc.id)}</title>
<style>
  *, *::before, *::after { box-sizing: border-box; }
  html { min-height: 100%; }
  body { margin: 0; min-height: 100vh; background: #f1f5f9; color: #111; font-family: Inter, Arial, sans-serif; }
  a { color: #1a73e8; }
  a:hover { text-decoration: underline; }
  .page-header {
    position: sticky;
    top: 0;
    z-index: 100;
    background: #1e293b;
    border-bottom: 2px solid #334155;
    box-shadow: 0 2px 12px rgba(0,0,0,0.25);
    padding: 14px 28px;
    display: flex;
    align-items: center;
    gap: 16px;
    flex-wrap: wrap;
  }
  .page-header-text { flex: 1; }
  .page-title { margin: 0 0 2px; font-size: 16px; color: #f1f5f9; font-weight: 700; }
  .page-subtitle { margin: 0; color: #94a3b8; font-size: 12px; }
  .section-label { display: inline-flex; align-items: center; gap: 10px; padding: 7px 14px; border-radius: 999px; background: #1a237e; color: #fff; font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 14px; }
  .content-wrap { max-width: 1100px; margin: 0 auto; padding: 28px 24px; }
  .full-section { background:#fff; padding: 32px; border-radius: 14px; box-shadow: 0 8px 32px rgba(15,23,42,0.08); margin-bottom: 28px; }
  .proof-frame { width: 100%; min-height: 80vh; border: none; border-radius: 10px; display: block; background: #fff; }
  .proof-image { width: 100%; max-width: 100%; display: block; margin: 0 auto; border-radius: 10px; object-fit: contain; }
</style>
</head>
<body>
<div class="page-header">
  <div class="page-header-text">
    <h1 class="page-title">Combined Job Card — ${xmlEscape(jc.id)}</h1>
    <p class="page-subtitle">${formatTruckLabelFromPlate(jc.plate)} &nbsp;·&nbsp; ${xmlEscape(jc.driver)}</p>
  </div>
</div>
<div class="content-wrap">
  <section class="full-section">
    <div class="section-label">Digital Job Card</div>
    ${digitalHtml}
  </section>
  <section class="full-section">
    <div class="section-label">Handwritten Proof</div>
    ${proofSection}
  </section>
</div>
</body>
</html>`;

                const win = window.open('', '_blank');
                if (!win) { showToast('Pop-up blocked — please allow pop-ups for this site'); return; }
                win.document.write(fullHtml);
                win.document.close();
            }

            /**
             * Downloads both documents as a single combined PDF.
             * - Image proofs: merged inline into one html2pdf render (single file).
             * - PDF proofs:   generates digital PDF then downloads the proof PDF separately,
             *                 and opens the combined preview so the user can print-to-PDF.
             */
            async function downloadCombinedJobCard(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) {
                    showToast('Job card not found');
                    return;
                }
                const proof = jc.handwrittenProof;

                if (!proof) {
                    // No proof — just download the digital card
                    downloadJobCardReportById(jobCardId);
                    return;
                }

                const isPdf = proofIsPdf(proof);
                if (!(typeof proof.data === 'string' && proof.data.startsWith('data:'))) {
                    // Proof lives on Google Drive (audit J10): a cross-origin file cannot be merged client-side.
                    showToast('Proof is stored on Google Drive — downloading the digital card and the proof separately');
                    downloadJobCardReportById(jobCardId);
                    setTimeout(() => downloadHandwrittenJobCard(jobCardId), 800);
                    return;
                }

                if (!isPdf) {
                    const digitalHtml = generateJobCardReportHtml(jc);
                    const combinedHtml = `
                        ${digitalHtml}
                        <div style="padding:32px 24px;font-family:Arial,sans-serif;color:#111;background:#fff;">
                            <div style="border-bottom:3px solid #c62828;padding-bottom:12px;margin-bottom:24px">
                                <h2 style="margin:0;color:#c62828;font-size:18px">HANDWRITTEN JOB CARD PROOF</h2>
                                <p style="margin:6px 0 0;color:#555;font-size:11px">${xmlEscape(proof.name)} · ${fmtBytes(proof.size)}</p>
                            </div>
                            <img src="${esc(proof.data)}" alt="Handwritten proof"
                                 style="width:100%;max-width:1000px;display:block;margin:0 auto;object-fit:contain;border:1px solid #ddd;border-radius:8px">
                        </div>`;
                    showToast('Generating combined PDF…');
                    downloadHtmlAsPdf(combinedHtml, `jobcard-${jc.id}-combined.pdf`);
                    return;
                }

                showToast('Generating combined PDF...');
                try {
                    const digitalHtml = generateJobCardReportHtml(jc);
                    const digitalBlob = await downloadHtmlAsPdfBlob(digitalHtml);
                    const proofBlob = dataUrlToBlob(proof.data);
                    const mergedBlob = await mergePdfBlobs(digitalBlob, proofBlob);
                    const fileName = `jobcard-${jc.id}-combined.pdf`;
                    const url = URL.createObjectURL(mergedBlob);
                    const a = document.createElement('a');
                    a.href = url;
                    a.download = fileName;
                    a.click();
                    setTimeout(() => URL.revokeObjectURL(url), 15000);
                    showToast('Combined PDF downloaded ✓');
                } catch (err) {
                    console.error('Combined PDF generation failed:', err);
                    showToast('Failed to create combined PDF. Downloading digital job card instead.');
                    downloadJobCardReportById(jobCardId);
                }
            }

            async function approveJobCard(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc || !isSupervisorRole()) { showToast('Supervisor or Admin role required'); return; }
                if (jc.status !== 'Pending-Approval') { showToast('Only cards pending approval can be approved'); return; }
                // The PIN is asked only when one is set, as everywhere else in the app (permanent delete,
                // restore, reset). Without this guard requireAdminPin answered "Set an admin PIN first" and
                // returned false, so with no PIN configured NOBODY could ever approve a job card.
                if (hasAdminPin() && !await requireAdminPin('Enter admin PIN to approve and release this job card')) return;
                const approver = getCurrentUserLabel(); // audit J12 / J-S1
                jc.status = 'Released';
                jc.approvedAt = new Date().toISOString();
                jc.releasedAt = jc.approvedAt;
                jc.approvedBy = approver;
                jc.approvedByRole = getFgRole();
                addAuditLog(jc, getFgRole(), 'approved and released', formatRwf(jcTotals(jc).actC));
                const trk = trucks.find(t => String(t.plate || '').trim().toUpperCase() === String(jc.plate || '').trim().toUpperCase());
                if (trk) {
                    if (!trk.lastServices) trk.lastServices = {};
                    if (!trk.maintenanceLog) trk.maintenanceLog = [];
                    const releaseDay = toYMD(new Date());
                    (jc.mechanicLines || []).filter(m => m.done).forEach(m => {
                        // Audit J7: planned lines use the driver line name, unplanned lines their own real name.
                        const dl = (jc.driverLines || []).find(d => d.lineId === m.driverLineId);
                        const name = (m.unplanned ? (m.name || '').trim() : (dl && dl.name)) || (m.name || '').trim() || 'Service';
                        const d = jcDoneDate(jc, m) || releaseDay; // Oct 2026: the job card's own service date
                        if (!trk.lastServices[name] || String(trk.lastServices[name]) < d) trk.lastServices[name] = d;
                        const dup = trk.maintenanceLog.some(x => x.jobCardId === jc.id && x.service === name && x.date === d);
                        if (!dup) trk.maintenanceLog.push({
                            date: d, service: name, jobCardId: jc.id,
                            cost: m.actualCost || 0, mechanic: m.mechanic || '', unplanned: !!m.unplanned, approvedBy: approver
                        });
                    });
                }
                setTruckGarageStatus(jc.plate, false);
                logAudit('jobcard.approve', 'jobCard', jc.id, `${jc.plate} released · ${formatRwf(jcTotals(jc).actC)}`);
                saveAll(['jobCards', 'trucks', 'auditTrail']);
                closeModal();
                renderJobCardsPage();
                showToast(`Truck ${jc.plate} released from garage`);
            }
            async function rejectJobCard(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                if (!isSupervisorRole()) { showToast('Supervisor or Admin role required to reject'); return; }
                if (jc.status !== 'Pending-Approval') { showToast('Only cards pending approval can be rejected'); return; }
                const reason = await promptDialog(`Reject ${jc.id} and return it to the mechanic. Please give a reason — it is recorded on the card.`, { title: 'Reject job card', inputLabel: 'Reason for rejection', inputRequired: true, okLabel: 'Reject', danger: true, inputPlaceholder: 'e.g. parts cost not justified' });
                if (reason === null || !String(reason).trim()) return;
                jc.status = 'In-Progress';
                jc.rejectionReason = String(reason).trim();
                jc.rejectedBy = getCurrentUserLabel();
                jc.rejectedAt = new Date().toISOString();
                if (!Array.isArray(jc.rejections)) jc.rejections = [];
                jc.rejections.push({ at: jc.rejectedAt, by: jc.rejectedBy, reason: jc.rejectionReason });
                addAuditLog(jc, getFgRole(), 'rejected — returned to mechanic', jc.rejectionReason);
                logAudit('jobcard.reject', 'jobCard', jc.id, jc.rejectionReason);
                saveAll(['jobCards', 'auditTrail']);
                closeModal();
                renderJobCardsPage();
                showToast('Returned to mechanic');
            }
            async function deleteJobCard(jobCardId) {
                const jc = jobCards.find(j => j.id === jobCardId);
                if (!jc) return;
                if (!(canActAsDriver() && jc.status === 'Draft') && !(canActAsMechanic() && jc.status === 'In-Progress') && !isSupervisorRole()) { showToast('Only draft cards (driver) or cards in progress (mechanic) can be deleted'); return; }
                const ok = await confirmDialog(`Move job card "${jc.id}" (${jc.plate || 'Vehicle'}) to the Recycling Bin?`, { danger: true, okLabel: 'Move to bin' });
                if (!ok) return;
                sendToRecycleBin('jobcard', `Job Card ${jc.id} (${jc.plate || 'Vehicle'})`, jc);
                jobCards = jobCards.filter(j => j.id !== jobCardId);
                logAudit('jobcard.delete', 'jobCard', jc.id, 'moved to recycle bin');
                saveAll(['jobCards', 'recycleBin', 'auditTrail']);
                renderJobCardsPage();
                showToast('Job card moved to Recycling Bin');
            }
            function passesHistoryPeriod(jc, period) {
                if (period === 'all') return true;
                const d = jcApprovalTimestamp(jc).slice(0, 10);
                if (!d) return period === 'recent';
                if (period === 'recent') return true;
                // Local calendar comparisons (brief rule 4).
                const now = new Date();
                const dt = parseYMD(d);
                if (!dt) return false;
                if (period === 'date') return d === todayYMD();
                if (period === 'week') return dt >= startOfWeek(now) && dt <= endOfDay(now);
                if (period === 'month') return dt >= startOfMonth(now) && dt <= endOfDay(now);
                return true;
            }
            // Audit J8: the ONE filtered set used by the History list, Print Report and Export CSV.
            function getFilteredHistoryCards() {
                const search = (document.getElementById('historySearch')?.value || '').toLowerCase();
                const truckFilter = document.getElementById('historyTruckFilter')?.value || '';
                const period = document.getElementById('historyPeriodFilter')?.value || 'recent';
                const filtered = jobCards.filter(jc => isSupervisorApproved(jc)).filter(jc => {
                    const ms = !search || (jc.id || '').toLowerCase().includes(search) || (jc.plate || '').toLowerCase().includes(search) || (getTrailerForPlate(jc.plate) || '').toLowerCase().includes(search) || (jc.driver || '').toLowerCase().includes(search);
                    const mt = !truckFilter || jc.plate === truckFilter;
                    return ms && mt && passesHistoryPeriod(jc, period);
                });
                filtered.sort((a, b) => jcApprovalTimestamp(b).localeCompare(jcApprovalTimestamp(a)));
                return filtered;
            }
            function renderJcHistory() {
                const filtered = getFilteredHistoryCards();
                const container = document.getElementById('jobCardHistoryList');
                if (!container) return;
                if (!filtered.length) {
                    container.innerHTML = '<div class="empty-state"><div class="e-icon">📑</div><p>No approved job cards in this period.</p></div>';
                    return;
                }
                const total = filtered.reduce((s, jc) => s + jcTotals(jc).actC, 0);
                container.innerHTML = `<div style="font-size:12px;color:var(--text3);margin-bottom:10px">${filtered.length} job card${filtered.length !== 1 ? 's' : ''} · Total ${formatRwf(total)} · PDF / Print / CSV use this filtered list</div>` + filtered.map(jc => {
                    const t = jcTotals(jc);
                    const id = escAttr(jc.id);
                    const approvedOn = jcApprovalTimestamp(jc).slice(0, 10);
                    const hasProof = !!jc.handwrittenProof;
                    return `<div class="rpt-panel-box" style="margin-bottom:14px">
                        <div class="rpt-panel-header"><span>${esc(jc.id)} · ${formatTruckLabelFromPlate(jc.plate || '')} · ${esc(jc.driver || '')} · Date: ${esc(jc.date || (jc.createdAt ? String(jc.createdAt).slice(0, 10) : '—'))}${jc.odometer ? ' · Odo: ' + esc(formatOdometer(jc.odometer)) : ''} · Approved</span>
                            <span style="color:var(--green)">${formatRwf(t.actC)}</span></div>
                        <div style="padding:14px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">
                            <button class="btn btn-sm btn-ghost" onclick="App.openJobCardPreview('${id}')">View</button>
                            <button class="btn btn-sm btn-ghost" onclick="App.downloadJobCardReportById('${id}')">⬇ PDF</button>
                            <button class="btn btn-sm btn-ghost" onclick="App.generateJobCardReportById('${id}')">Print</button>
                            <button class="btn btn-sm btn-ghost" onclick="App.exportJobCardCsv('${id}')">CSV</button>
                            ${hasProof ? `<button class="btn btn-sm btn-handwritten" onclick="App.viewHandwrittenProof('${id}')">📋 View Handwritten Job Card</button>
                                          <button class="btn btn-sm btn-ghost" onclick="App.replaceHandwrittenProof('${id}')">🔄 Replace Proof</button>`
                                       : `<button class="btn btn-sm btn-outline" onclick="App.attachHandwrittenProof('${id}')">📎 Attach Handwritten Card</button>`}
                        </div>
                    </div>`;
                }).join('');
            }
            function generateJobCardReportHtml(jc) {
                migrateJobCard(jc);
                const t = jcTotals(jc);
                const trk = trucks.find(x => x.plate === jc.plate);
                const driverRows = (jc.driverLines || []).map(dl => {
                    const hist = findLastServiceFromHistory(jc.plate, dl.name, jc.id, jcPriorCutoff(jc, dl.name));
                    return `<tr>
                        <td style="border:1px solid #cbd5e1;padding:7px 10px;font-size:12px">${esc(dl.name)}</td>
                        <td style="border:1px solid #cbd5e1;padding:7px 10px;font-size:11px;color:#475569">${hist ? esc(hist.date) + (hist.jobCardId ? ' (' + esc(hist.jobCardId) + ')' : '') : 'Never'}</td>
                    </tr>`;
                }).join('');
                const mechRows = (jc.mechanicLines || []).filter(m => m.done).map(m => {
                    const dl = (jc.driverLines || []).find(d => d.lineId === m.driverLineId);
                    const label = m.unplanned ? (m.name || 'Extra work') : (dl?.name || 'Service');
                    return `<tr>
                        <td style="border:1px solid #cbd5e1;padding:7px 10px;font-size:12px">${esc(label)}${m.unplanned ? ' <span style="color:#0d9488">(extra)</span>' : ''}${m.comment ? `<div style="font-size:10.5px;color:#475569;margin-top:2px">Comment: ${esc(m.comment)}</div>` : ''}</td>
                        <td style="border:1px solid #cbd5e1;padding:7px 10px;text-align:right;font-size:12px">${formatRwf(m.partsCost || 0)}</td>
                        <td style="border:1px solid #cbd5e1;padding:7px 10px;text-align:right;font-size:12px">${formatRwf(m.labourCost || 0)}</td>
                        <td style="border:1px solid #cbd5e1;padding:7px 10px;text-align:right;font-size:12px;font-weight:600">${formatRwf(m.actualCost || 0)}</td>
                        <td style="border:1px solid #cbd5e1;padding:7px 10px;font-size:12px">${esc(jcPersonName(m.mechanic))}</td>
                    </tr>`;
                }).join('');
                // Audit J13: letterhead comes from the company profile (Settings), never hard-coded.
                const co = getCompany();
                const _jcLogoUri = co.logo || '';
                const _wmUri = _jcLogoUri;
                const contactLines = [co.address, co.phone ? 'Tel: ' + co.phone : '', co.email ? 'Email: ' + co.email : ''].filter(Boolean).map(esc).join('<br>');
                // Oct 2026: the card shows no account e-mail and no date but the SERVICE date (jc.date).
                const serviceDate = jc.date || (jc.createdAt ? String(jc.createdAt).slice(0, 10) : '');
                const mechanicNames = [...new Set((jc.mechanicLines || []).filter(m => m.done).map(m => jcPersonName(m.mechanic)).filter(Boolean))].join(', ');
                // class jc-print-card: the PDF, the print window and the digital card give it a full A4 page's
                // height, so the faint logo below is centred on the PAGE, not just on the content.
                return `<div class="jc-print-card" style="font-family:'Segoe UI',Helvetica,Arial,sans-serif;width:100%;max-width:800px;margin:0 auto;padding:0;background:#fff;color:#0f172a;box-sizing:border-box;position:relative;overflow:hidden;">

                    <!-- ===== LETTERHEAD ===== -->
                    <div style="position:relative;">
                        <!-- Red top bar -->
                        <div style="height:16px;background:#ec0000;width:100%;"></div>
                        <!-- Black wave -->
                        <svg style="display:block;width:100%;height:34px;" viewBox="0 0 1000 40" preserveAspectRatio="none">
                            <path d="M0,0 L1000,0 L1000,14 C820,38 680,6 520,20 C360,34 200,4 0,18 Z" fill="#000000"></path>
                        </svg>
                        <!-- Logo + Company + Contact -->
                        <div style="display:flex;align-items:center;justify-content:space-between;gap:14px;padding:6px 24px 14px 24px;">
                            ${_jcLogoUri ? `<img src="${esc(_jcLogoUri)}" alt="${esc(co.shortName)} logo" style="height:90px;width:auto;flex-shrink:0;">` : '<div style="width:90px"></div>'}
                            <div style="flex:1;text-align:center;">
                                <div style="margin:0 0 4px 0;font-size:24px;font-weight:800;color:#ec0000;letter-spacing:0.01em;">${esc(co.name)}</div>
                                <div style="margin:0;font-size:11px;font-weight:700;color:#000000;letter-spacing:0.06em;text-transform:uppercase;">Maintenance &nbsp;-&nbsp; Job Card</div>
                            </div>
                            <div style="text-align:right;font-size:11px;font-weight:700;color:#000000;line-height:1.5;flex-shrink:0;white-space:nowrap;">
                                ${contactLines}
                            </div>
                        </div>
                        <!-- Black divider -->
                        <div style="height:5px;background:#000000;width:100%;"></div>
                    </div>

                    <!-- ===== WATERMARK ===== -->
                    ${_wmUri ? `<div style="position:absolute;top:0;left:0;right:0;bottom:0;display:flex;align-items:center;justify-content:center;z-index:0;pointer-events:none;"><img src="${esc(_wmUri)}" alt="" style="width:600px;max-width:82%;height:auto;opacity:0.10;"></div>` : ''}

                    <!-- ===== BODY ===== -->
                    <div style="position:relative;z-index:1;padding:16px 20px;">

                        <!-- Info block -->
                        <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;background:#f8fafc;padding:10px 14px;border:1px solid #e2e8f0;border-radius:6px;margin-bottom:14px;font-size:12px;">
                            <div><strong>Job card:</strong> ${esc(jc.id)} &nbsp;&middot;&nbsp; <strong>Truck:</strong> ${formatTruckLabelFromPlate(jc.plate)}${trk?.model ? ' &middot; ' + esc(trk.model) : ''} &nbsp;&middot;&nbsp; <strong>Health:</strong> ${trk ? healthScore(trk) + '%' : 'N/A'}</div>
                            <div><strong>Driver:</strong> ${esc(jcPersonName(jc.driver) || '—')}</div>
                            <div><strong>Job card date:</strong> ${serviceDate ? esc(formatDisplayDate(serviceDate)) : 'N/A'} &nbsp;&middot;&nbsp; <strong>Odometer:</strong> ${jc.odometer ? esc(formatOdometer(jc.odometer)) : 'N/A'}</div>
                            ${jc.rejectionReason ? `<div style="color:#b45309"><strong>Last rejection:</strong> ${esc(jc.rejectionReason)}</div>` : ''}
                        </div>

                        <!-- Section 1 -->
                        <h3 style="margin:12px 0 6px 0;font-size:13px;font-weight:700;color:#1e293b;text-transform:uppercase;letter-spacing:0.03em;">1. Driver Service Requests</h3>
                        <table style="width:100%;border-collapse:collapse;margin-bottom:14px;">
                            <thead>
                                <tr style="background:#f1f5f9;font-size:11px;text-transform:uppercase;color:#334155;">
                                    <th style="border:1px solid #cbd5e1;padding:6px 10px;text-align:left;">Service Requested</th>
                                    <th style="border:1px solid #cbd5e1;padding:6px 10px;text-align:left;">Prior Service Record</th>
                                </tr>
                            </thead>
                            <tbody>${driverRows || '<tr><td colspan="2" style="padding:8px;text-align:center;color:#94a3b8;">&mdash; No driver lines &mdash;</td></tr>'}</tbody>
                        </table>

                        <!-- Section 2 -->
                        <h3 style="margin:14px 0 6px 0;font-size:13px;font-weight:700;color:#1e293b;text-transform:uppercase;letter-spacing:0.03em;">2. Mechanic Completion &amp; Expenses (RWF)</h3>
                        <table style="width:100%;border-collapse:collapse;margin-bottom:16px;">
                            <thead>
                                <tr style="background:#f1f5f9;font-size:11px;text-transform:uppercase;color:#334155;">
                                    <th style="border:1px solid #cbd5e1;padding:6px 10px;text-align:left;">Service</th>
                                    <th style="border:1px solid #cbd5e1;padding:6px 10px;text-align:right;">Parts (RWF)</th>
                                    <th style="border:1px solid #cbd5e1;padding:6px 10px;text-align:right;">Labour (RWF)</th>
                                    <th style="border:1px solid #cbd5e1;padding:6px 10px;text-align:right;">Total (RWF)</th>
                                    <th style="border:1px solid #cbd5e1;padding:6px 10px;text-align:left;">Mechanic</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${mechRows || '<tr><td colspan="5" style="padding:8px;text-align:center;color:#94a3b8;">&mdash; No completed lines &mdash;</td></tr>'}
                                <tr style="font-weight:700;background:#f8fafc;">
                                    <td style="border:1px solid #cbd5e1;padding:7px 10px;font-size:12px;">TOTAL</td>
                                    <td style="border:1px solid #cbd5e1;padding:7px 10px;text-align:right;font-size:12px;">${formatRwf(t.actP)}</td>
                                    <td style="border:1px solid #cbd5e1;padding:7px 10px;text-align:right;font-size:12px;">${formatRwf(t.actL)}</td>
                                    <td style="border:1px solid #cbd5e1;padding:7px 10px;text-align:right;font-size:12px;color:#0f172a;">${formatRwf(t.actC)}</td>
                                    <td style="border:1px solid #cbd5e1;padding:7px 10px;"></td>
                                </tr>
                            </tbody>
                        </table>


                        <!-- Signatures -->
                        <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;margin-top:28px;text-align:center;font-size:11px;color:#475569;">
                            <div>____________________<br><strong style="color:#0f172a;">Driver Signature</strong><br><span style="font-size:10px">${esc(jcPersonName(jc.driver))}</span></div>
                            <div>____________________<br><strong style="color:#0f172a;">Mechanic Signature</strong><br><span style="font-size:10px">${esc(mechanicNames)}</span></div>
                            <div>____________________<br><strong style="color:#0f172a;">Supervisor Signature</strong><br><span style="font-size:10px">&nbsp;</span></div>
                        </div>
                        <div style="margin-top:14px;font-size:9px;color:#94a3b8;text-align:right;">${esc(co.name)}</div>

                    </div>
                </div>`;
            }
            function generateJobCardReport(jc) {
                if (!jc) return;
                const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>${jc.id}</title><style>body{margin:0;padding:0;background:#fff;font-family:'Segoe UI',Arial,sans-serif;}@page{size:A4;margin:10mm}@media print{body{margin:0;padding:0;}.jc-print-card{min-height:270mm}}</style></head><body>${generateJobCardReportHtml(jc)}</body></html>`;
                const win = window.open('', '_blank');
                if (!win) { showToast('Pop-up blocked — allow pop-ups to print'); return; }
                win.document.write(html);
                win.document.close();
                printWhenReady(win);
            }
            function downloadJobCardReport() {
                const filtered = getFilteredHistoryCards(); // audit J8
                if (!filtered.length) { showToast('No released job cards match the current filter'); return; }
                const body = filtered.map(jc => generateJobCardReportHtml(jc)).join('<div style="page-break-after:always"></div>');
                const win = window.open('', '_blank');
                if (!win) { showToast('Pop-up blocked — allow pop-ups to print'); return; }
                win.document.write(`<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>${esc(getCompanyName())} — Job Cards</title><style>body{margin:0;padding:0;background:#fff;font-family:'Segoe UI',Arial,sans-serif;}@page{size:A4;margin:10mm}@media print{body{margin:0;padding:0;}.jc-print-card{min-height:270mm}}</style></head><body>${body}</body></html>`);
                win.document.close();
                printWhenReady(win);
            }
            // History tab → ⬇ PDF: the filtered cards in one file, each card starting on its own page.
            async function downloadJobCardHistoryPdf() {
                const filtered = getFilteredHistoryCards();
                if (!filtered.length) { showToast('No released job cards match the current filter'); return; }
                try {
                    const res = await buildPdfDocument(filtered.map(jc => generateJobCardReportHtml(jc)),
                        `${(getCompany().shortName || 'Fleet').replace(/[^A-Za-z0-9_-]+/g, '-')}-job-cards-${todayYMD()}.pdf`, JC_PDF_CSS, `Building ${filtered.length} job card${filtered.length === 1 ? '' : 's'}`);
                    logAudit('export', 'jobCard', '', `PDF of ${filtered.length} job card(s)`);
                    saveAll(['auditTrail']);
                    showToast(`PDF downloaded ✓ (${filtered.length} job card${filtered.length === 1 ? '' : 's'}, ${res.pages} pages)`);
                } catch (err) {
                    console.error('Job card PDF failed:', err);
                    showToast('Could not build the PDF — ' + ((err && err.message) || 'unknown error') + '. Opening the print view instead.', 6000);
                    downloadJobCardReport();
                }
            }
            function exportJobCardCsv(singleId) {
                // Audit J8: without a single id, export exactly what the History tab is showing.
                let list = singleId ? jobCards.filter(j => j.id === singleId && isSupervisorApproved(j)) : getFilteredHistoryCards();
                if (!list.length) { showToast('No released job cards match the current filter'); return; }
                const rows = [['JobCardID', 'DateCreated', 'Odometer', 'ApprovedDate', 'ApprovedBy', 'Plate', 'Driver', 'Service', 'PartsCostRWF', 'LabourCostRWF', 'TotalCostRWF', 'Mechanic', 'CompletedAt', 'Extra', 'PriorServiceDate', 'PriorJobCard']];
                list.forEach(jc => {
                    migrateJobCard(jc);
                    const createdDate = jc.date || (jc.createdAt ? String(jc.createdAt).slice(0, 10) : '');
                    const odo = jc.odometer || '';
                    (jc.mechanicLines || []).filter(m => m.done).forEach(m => {
                        const dl = (jc.driverLines || []).find(d => d.lineId === m.driverLineId);
                        const name = m.unplanned ? (m.name || 'Extra work') : (dl?.name || 'Service');
                        const hist = findLastServiceFromHistory(jc.plate, name, jc.id, jcPriorCutoff(jc, name));
                        rows.push([
                            jc.id, createdDate, odo, jcApprovalTimestamp(jc).slice(0, 10), jc.approvedBy || '', jc.plate, jc.driver, name,
                            m.partsCost || 0, m.labourCost || 0, m.actualCost || 0, m.mechanic || '',
                            m.completedAt ? String(m.completedAt).slice(0, 10) : '',
                            m.unplanned ? 'Yes' : 'No',
                            hist?.date || '', hist?.jobCardId || ''
                        ]);
                    });
                });
                const csv = rows.map(r => r.map(c => `"${String(c == null ? '' : c).replace(/"/g, '""')}"`).join(',')).join('\n');
                const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8' });
                const a = document.createElement('a');
                a.href = URL.createObjectURL(blob);
                a.download = singleId ? `jobcard-${String(singleId).replace(/[^A-Za-z0-9_-]+/g, '_')}.csv` : `jobcards-finance-${todayYMD()}.csv`;
                document.body.appendChild(a); a.click(); a.remove();
                setTimeout(() => URL.revokeObjectURL(a.href), 2000);
                showToast(`CSV downloaded (${list.length} job card${list.length !== 1 ? 's' : ''})`);
            }

